//#region src/main/ts/armyc2/c5isr/graphics2d/Point.ts
/**
*
*
*/
var Point = class Point {
	x = 0;
	y = 0;
	constructor(...args) {
		switch (args.length) {
			case 0:
				this.setLocation(0, 0);
				break;
			case 2: {
				const [x1, y1] = args;
				this.setLocation(x1, y1);
				break;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
	getX() {
		return this.x;
	}
	getY() {
		return this.y;
	}
	setLocation(x1, y1) {
		this.x = Math.trunc(x1);
		this.y = Math.trunc(y1);
	}
	/**
	* Returns a string representing one of the shape types
	* from "armyc2.c2sd.renderer.so.ShapeTypes"
	* @returns {String} 
	*/
	getShapeType() {
		return "POINT";
	}
	/**
	* move x & y by specified amounts.
	* @param {Number} x shift x point by this value
	* @param {Number} y shift y point by this value
	* @returns {void}
	*/
	shift(x, y) {
		this.x += x;
		this.y += y;
	}
	/**
	* @returns {String} like "{x:#,y:#}"
	*/
	toStringFormatted() {
		return "{x:" + this.x + ", y:" + this.y + "}";
	}
	/**
	* Makes a copy of this point object.
	* @returns {armyc2.c2sd.renderer.so.Point} Copy of original point.
	*/
	clone() {
		return new Point(this.x, this.y);
	}
	toPoint2D() {
		return new Point2D(this.x, this.y);
	}
	/**
	* @param {OffscreenCanvasRenderingContext2D} context object from html5 canvas
	* @returns {void}
	*/
	setPath(context) {
		let x = this.x;
		let y = this.y;
		context.moveTo(x, y);
		context.lineTo(x + 1, y);
		context.lineTo(x + 1, y + 1);
		context.lineTo(x, y + 1);
		context.closePath();
	}
	/**
	* @param {context} context object from html5 canvas
	* @returns {void}
	*/
	stroke(context) {
		context.beginPath();
		this.setPath(context);
		context.stroke();
	}
	/**
	* @param {context} context object from html5 canvas
	* @returns {void}
	*/
	fill(context) {
		context.beginPath();
		this.setPath(context);
		context.fill();
	}
};

