//#region src/main/ts/armyc2/c5isr/renderer/utilities/Color.ts
/**
* Integer based Color class with utility functions
*/
var Color = class Color {
	/**
	* The color white.  In the default sRGB space.
	*/
	static white = new Color(255, 255, 255);
	/**
	* The color white.  In the default sRGB space.
	*
	*/
	static WHITE = Color.white;
	/**
	* The color light gray.  In the default sRGB space.
	*/
	static lightGray = new Color(192, 192, 192);
	/**
	* The color light gray.  In the default sRGB space.
	*
	*/
	static LIGHT_GRAY = Color.lightGray;
	/**
	* The color gray.  In the default sRGB space.
	*/
	static gray = new Color(128, 128, 128);
	/**
	* The color gray.  In the default sRGB space.
	*
	*/
	static GRAY = Color.gray;
	/**
	* The color dark gray.  In the default sRGB space.
	*/
	static darkGray = new Color(64, 64, 64);
	/**
	* The color dark gray.  In the default sRGB space.
	*
	*/
	static DARK_GRAY = Color.darkGray;
	/**
	* The color black.  In the default sRGB space.
	*/
	static black = new Color(0, 0, 0);
	/**
	* The color black.  In the default sRGB space.
	*
	*/
	static BLACK = Color.black;
	/**
	* The color red.  In the default sRGB space.
	*/
	static red = new Color(255, 0, 0);
	/**
	* The color red.  In the default sRGB space.
	*
	*/
	static RED = Color.red;
	/**
	* The color pink.  In the default sRGB space.
	*/
	static pink = new Color(255, 175, 175);
	/**
	* The color pink.  In the default sRGB space.
	*
	*/
	static PINK = Color.pink;
	/**
	* The color orange.  In the default sRGB space.
	*/
	static orange = new Color(255, 128, 0);
	/**
	* The color orange.  In the default sRGB space.
	*
	*/
	static ORANGE = Color.orange;
	/**
	* The color yellow.  In the default sRGB space.
	*/
	static yellow = new Color(255, 255, 0);
	/**
	* The color yellow.  In the default sRGB space.
	*
	*/
	static YELLOW = Color.yellow;
	/**
	* The color green.  In the default sRGB space.
	*/
	static green = new Color(0, 255, 0);
	/**
	* The color green.  In the default sRGB space.
	*
	*/
	static GREEN = Color.green;
	/**
	* The color magenta.  In the default sRGB space.
	*/
	static magenta = new Color(255, 0, 255);
	/**
	* The color magenta.  In the default sRGB space.
	*
	*/
	static MAGENTA = Color.magenta;
	/**
	* The color cyan.  In the default sRGB space.
	*/
	static cyan = new Color(0, 255, 255);
	/**
	* The color cyan.  In the default sRGB space.
	*
	*/
	static CYAN = Color.cyan;
	/**
	* The color blue.  In the default sRGB space.
	*/
	static blue = new Color(0, 0, 255);
	/**
	* The color blue.  In the default sRGB space.
	*
	*/
	static BLUE = Color.blue;
	_A = 255;
	_R = 0;
	_G = 0;
	_B = 0;
	/**
	*
	* @param hexValue - String representing hex value (formatted "0xRRGGBB"
	* i.e. "0xFFFFFF") OR formatted "0xAARRGGBB" i.e. "0x00FFFFFF" for a color
	* with an alpha value I will also put up with "RRGGBB" and "AARRGGBB"
	* without the starting "0x" or "#"
	* @return
	*/
	getColorsFromHexString(hexValue) {
		try {
			if (hexValue == null || hexValue.length === 0) return null;
			let hexOriginal = hexValue;
			let hexAlphabet = "0123456789ABCDEF";
			if (hexValue.charAt(0) === "#") hexValue = hexValue.substring(1);
			if (hexValue.substring(0, 2) === "0x" || hexValue.substring(0, 2) === "0X") hexValue = hexValue.substring(2);
			hexValue = hexValue.toUpperCase();
			let count = hexValue.length;
			let value;
			let k = 0;
			let int1 = 0;
			let int2 = 0;
			if (count === 8 || count === 6) {
				value = new Array(count / 2);
				for (let i = 0; i < count; i += 2) {
					int1 = hexAlphabet.indexOf(hexValue.charAt(i));
					int2 = hexAlphabet.indexOf(hexValue.charAt(i + 1));
					if (int1 === -1 || int2 === -1) throw Error("Bad hex value: " + hexOriginal);
					value[k] = int1 * 16 + int2;
					k++;
				}
				return value;
			} else throw Error("Bad hex value: " + hexValue);
			return null;
		} catch (exc) {
			if (exc instanceof Error) throw Error("Bad hex value: " + hexValue);
			else throw exc;
		}
		return null;
	}
	constructor(...args) {
		switch (args.length) {
			case 1:
				if (args[0] instanceof Color) {
					const [color] = args;
					if (color != null) {
						this._A = color.getAlpha();
						this._R = color.getRed();
						this._G = color.getGreen();
						this._B = color.getBlue();
					} else {
						this._A = 255;
						this._R = 0;
						this._G = 0;
						this._B = 0;
					}
				} else if (typeof args[0] === "string") {
					const [hexString] = args;
					let arr = this.getColorsFromHexString(hexString);
					if (arr != null && (arr.length === 4 || arr.length === 3)) if (arr.length === 4) {
						this._A = arr[0];
						this._R = arr[1];
						this._G = arr[2];
						this._B = arr[3];
					} else {
						this._A = 255;
						this._R = arr[0];
						this._G = arr[1];
						this._B = arr[2];
					}
				} else if (typeof args[0] === "number") {
					const [color] = args;
					this._A = this.getAlphaFromColor(color);
					this._R = this.getRedFromColor(color);
					this._G = this.getGreenFromColor(color);
					this._B = this.getBlueFromColor(color);
				} else {
					this._A = 255;
					this._R = 0;
					this._G = 0;
					this._B = 0;
				}
				break;
			case 3: {
				const [R, G, B] = args;
				this._A = 255;
				this._R = R;
				this._G = G;
				this._B = B;
				break;
			}
			case 4: {
				const [R, G, B, A] = args;
				this._A = A;
				this._R = R;
				this._G = G;
				this._B = B;
				break;
			}
			case 0:
				this._A = 255;
				this._R = 0;
				this._G = 0;
				this._B = 0;
				break;
			default: throw new Error("Color() - Invalid number of arguments");
		}
	}
	static makeColor(r, g, b) {
		let color = null;
		try {
			color = new Color(r, g, b);
		} catch (e) {
			if (e instanceof Error) console.log(e.message);
		}
		return color;
	}
	toRGB() {
		return this._R * 65536 + this._G * 256 + this._B;
	}
	toARGB() {
		let returnVal = 0;
		returnVal = (this._A << 24) + ((this._R & 255) << 16) + ((this._G & 255) << 8) + (this._B & 255);
		return returnVal;
	}
	convert(integer) {
		var hexAlphabet = "0123456789ABCDEF";
		return isNaN(integer) ? "00" : hexAlphabet.charAt((integer - integer % 16) / 16) + hexAlphabet.charAt(integer % 16);
	}
	/**
	* A hex string in the format of AARRGGBB
	* @param {Boolean} withAlpha Optional, default is true. If set to false,
	* will return a hex string without alpha values.
	*/
	toHexString(withAlpha = false) {
		if (withAlpha === false) return "#" + this.convert(this._R) + this.convert(this._G) + this.convert(this._B);
		else return "#" + this.convert(this._A) + this.convert(this._R) + this.convert(this._G) + this.convert(this._B);
	}
	toString() {
		return "Color{A=" + this._A.toString() + ",R=" + this._R.toString() + ",G=" + this._G.toString() + ",B=" + this._B.toString() + "}";
	}
	getRed() {
		return this._R;
	}
	getGreen() {
		return this._G;
	}
	getBlue() {
		return this._B;
	}
	getAlpha() {
		return this._A;
	}
	/**
	*
	* @param alpha 0-255
	*/
	setAlpha(alpha) {
		this._A = alpha;
	}
	toInt() {
		return this.toARGB();
	}
	/**
	* get alpha value from uint
	* */
	getAlphaFromColor(color) {
		let alpha = 255;
		if (color > 16777215) alpha = color >>> 24;
		return alpha;
	}
	/**
	* get red value from uint
	* */
	getRedFromColor(color) {
		let red = 255;
		red = color >> 16 & 255;
		return red;
	}
	/**
	* get green value from uint
	* */
	getGreenFromColor(color) {
		let green = 255;
		green = color >> 8 & 255;
		return green;
	}
	/**
	* get blue value from uint
	* */
	getBlueFromColor(color) {
		let blue = 255;
		if (color > 16777215) blue = color & 255;
		else blue = color & 255;
		return blue;
	}
};

