//#region src/main/ts/armyc2/c5isr/graphics2d/Rectangle2D.ts
/**
*
*
*/
var Rectangle2D = class Rectangle2D {
	x = 0;
	y = 0;
	width = 0;
	height = 0;
	add(newx, newy) {
		const x1 = Math.min(this.getMinX(), newx);
		const x2 = Math.max(this.getMaxX(), newx);
		const y1 = Math.min(this.getMinY(), newy);
		const y2 = Math.max(this.getMaxY(), newy);
		this.setRect(x1, y1, x2 - x1, y2 - y1);
	}
	createIntersection(r) {
		if (r.x > this.x + this.width) return null;
		if (r.x + r.width < this.x) return null;
		if (r.y > this.y + this.height) return null;
		if (r.y + r.height < this.y) return null;
		if (r.contains(this)) return this;
		if (this.contains(r)) return r;
		let x1 = 0;
		let y1 = 0;
		let x2 = 0;
		let y2 = 0;
		if (this.x < r.x) {
			x1 = r.x;
			x2 = this.x + this.width;
		} else {
			x1 = this.x;
			x2 = r.x + r.width;
		}
		if (this.y < r.y) {
			y1 = r.y;
			y2 = this.y + this.height;
		} else {
			y1 = this.y;
			y2 = r.y + r.height;
		}
		return new Rectangle2D(x1, y1, x2 - x1, y2 - y1);
	}
	createUnion(r) {
		let temp = this.clone();
		temp.union(r);
		return temp;
	}
	getX() {
		return this.x;
	}
	getY() {
		return this.y;
	}
	getCenterX() {
		return (this.x + this.width) / 2;
	}
	getCenterY() {
		return (this.y + this.height) / 2;
	}
	getMinX() {
		return this.x;
	}
	getMinY() {
		return this.y;
	}
	getMaxX() {
		return this.x + this.width;
	}
	getMaxY() {
		return this.y + this.height;
	}
	getHeight() {
		return this.height;
	}
	getWidth() {
		return this.width;
	}
	contains(...args) {
		switch (args.length) {
			case 1: if (args[0] instanceof Rectangle2D) {
				const [rect] = args;
				let x1 = rect.getX();
				let y1 = rect.getY();
				if (this.contains(x1, y1)) {
					x1 += rect.getWidth();
					y1 += rect.getHeight();
					if (this.contains(x1, y1)) return true;
				}
				return false;
			} else {
				const [pt] = args;
				if (this.x <= pt.getX() && pt.getX() <= this.x + this.width) {
					if (this.y <= pt.getY() && pt.getY() <= this.y + this.height) return true;
				}
				return false;
			}
			case 2: {
				const [x1, y1] = args;
				if (this.x <= x1 && x1 <= this.x + this.width && this.y <= y1 && y1 <= this.y + this.height) return true;
				else return false;
			}
			case 4: {
				const [x, y, width, height] = args;
				let x1 = x;
				let y1 = y;
				if (this.contains(x1, y1)) {
					x1 += width;
					y1 += height;
					if (this.contains(x1, y1)) return true;
				}
				return false;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
	intersects(...args) {
		switch (args.length) {
			case 1: {
				const [rect] = args;
				if (this.x + this.width < rect.x) return false;
				if (this.x > rect.x + rect.width) return false;
				if (this.y + this.height < rect.y) return false;
				if (this.y > rect.y + rect.height) return false;
				return true;
			}
			case 4: {
				const [x1, y1, width1, height1] = args;
				if (this.x + this.width < x1) return false;
				if (this.x > x1 + width1) return false;
				if (this.y + this.height < y1) return false;
				if (this.y > y1 + height1) return false;
				return true;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
	intersectsLine(line) {
		return false;
	}
	isEmpty() {
		if (this.width === 0 && this.height === 0) return true;
		else return false;
	}
	setRect(...args) {
		switch (args.length) {
			case 1: {
				const [r] = args;
				this.x = r.getX();
				this.y = r.getY();
				this.width = r.getWidth();
				this.height = r.getHeight();
				break;
			}
			case 4: {
				const [x1, y1, width1, height1] = args;
				this.x = x1;
				this.y = y1;
				this.width = width1;
				this.height = height1;
				break;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
	grow(...args) {
		switch (args.length) {
			case 1: {
				const [size] = args;
				this.x = this.x - size;
				this.y = this.y - size;
				this.width = this.width + 2 * size;
				this.height = this.height + 2 * size;
				break;
			}
			case 2: {
				const [h, v] = args;
				this.x = this.x - h;
				this.y = this.y - v;
				this.width = this.width + 2 * h;
				this.height = this.height + 2 * v;
				break;
			}
		}
	}
	stroke(context) {
		context.strokeRect(this.getX(), this.getY(), this.getWidth(), this.getHeight());
	}
	fill(context) {
		context.fillRect(this.getX(), this.getY(), this.getWidth(), this.getHeight());
	}
	clone() {
		return new Rectangle2D(this.x, this.y, this.width, this.height);
	}
	/**
	* Will merge the bounds of two rectangle.
	* @param rect 
	*/
	union(rect) {
		let thisBR = new Point2D(this.x + this.width, this.y + this.height);
		let rectBR = new Point2D(rect.x + rect.width, rect.y + rect.height);
		let x;
		let y;
		let bottom;
		let right;
		if (rect) {
			if (rect.y < this.y) y = rect.y;
			else y = this.y;
			if (rect.x < this.x) x = rect.x;
			else x = this.x;
			if (rectBR.getY() > thisBR.getY()) bottom = rectBR.getY();
			else bottom = thisBR.getY();
			if (rectBR.getX() > thisBR.getX()) right = rectBR.getX();
			else right = thisBR.getX();
			this.setRect(x, y, right - x, bottom - y);
		}
	}
	constructor(...args) {
		switch (args.length) {
			case 0:
				this.x = 0;
				this.y = 0;
				this.width = 0;
				this.height = 0;
				break;
			case 4: {
				const [x1, y1, width1, height1] = args;
				this.x = x1;
				this.y = y1;
				this.width = width1;
				this.height = height1;
				break;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
	/**
	* 
	* @param stroke named color or hex color
	* @param strokeWidth width of line in # of pixels
	* @param fill named color or hex color
	* @returns 
	*/
	toSVGElement(stroke, strokeWidth, fill) {
		var line = "<rect x=\"" + this.x + "\" y=\"" + this.y;
		line += "\" width=\"" + this.width + "\" height=\"" + this.height + "\"";
		if (strokeWidth) line += " stroke-width=\"" + strokeWidth + "\"";
		else if (stroke) line += " stroke-width=\"2\"";
		if (stroke) line += " stroke=\"" + stroke + "\"";
		if (fill) line += " fill=\"" + fill + "\"";
		else line += " fill=\"none\"";
		line += "/>";
		return line;
	}
};

