//#region src/main/ts/armyc2/c5isr/renderer/utilities/RendererUtilities.ts
var RendererUtilities = class RendererUtilities {
	static OUTLINE_SCALING_FACTOR = 2.5;
	static async imgToBase64String(img) {
		img.getContext("2d");
		let blob = await img.convertToBlob();
		const dataURL = new FileReader().readAsDataURL(blob);
		return new String(dataURL).toString();
	}
	static pastIdealOutlineColors = /* @__PURE__ */ new Map();
	/**
	* 
	* @param color {String} color like "#FFFFFF"
	* @return {String}
	*/
	static getIdealOutlineColor(color) {
		let idealColor = Color.white;
		if (color != null && RendererUtilities.pastIdealOutlineColors.has(color.toInt())) return RendererUtilities.pastIdealOutlineColors.get(color.toInt());
		if (color != null) {
			let threshold = RendererSettings.getInstance().getTextBackgroundAutoColorThreshold();
			let r = color.getRed();
			let g = color.getGreen();
			let b = color.getBlue();
			if (255 - (r * .299 + g * .587 + b * .114) < threshold) idealColor = Color.black;
			else idealColor = Color.white;
		}
		if (color != null) RendererUtilities.pastIdealOutlineColors.set(color.toInt(), idealColor);
		return idealColor;
	}
	/**
	* Create a copy of the {@Color} object with the passed alpha value.
	* @param color {@Color} object used for RGB values
	* @param alpha {@float} value between 0 and 1
	* @return
	*/
	static setColorAlpha(color, alpha) {
		if (color != null) if (alpha >= 0 && alpha <= 1) return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.trunc(alpha * 255));
		else return color;
		else return null;
	}
	/**
	*
	* @param color
	* @return 8 character hex code, will have to prepend '#' or '0x' depending on your usage
	*/
	static ColorToHex(color) {
		return color.getAlpha().toString(16).padStart(2, "0") + color.getRed().toString(16).padStart(2, "0") + color.getGreen().toString(16).padStart(2, "0") + color.getBlue().toString(16).padStart(2, "0");
	}
	/**
	*
	* @param color
	* @param withAlpha
	* @return
	*/
	static colorToHexString(color, withAlpha) {
		if (color != null) return color.toHexString(withAlpha);
		else return "";
	}
	static measureText(...args) {
		let bounds;
		switch (args.length) {
			case 2: {
				const [text, context] = args;
				if (arguments.length === 4) {
					let tm = context.measureText(text);
					let top = tm.fontBoundingBoxAscent - 1;
					let left = -1;
					let width = tm.width + 2;
					width = tm.actualBoundingBoxRight + tm.actualBoundingBoxLeft;
					let height = tm.fontBoundingBoxDescent + tm.fontBoundingBoxAscent + 2;
					bounds = new Rectangle2D(top, left, width, height);
				}
				break;
			}
			case 3: {
				const [font, text, context] = args;
				if (arguments.length === 3) {
					let ctx;
					if (context == null) {
						ctx = new OffscreenCanvas(10, 10).getContext("2d");
						ctx.font = font;
						bounds = this.measureText(text, ctx);
					} else bounds = this.measureText(text, context);
				}
				break;
			}
			case 5: {
				const [fontName, fontSize, fontStyle, text, context] = args;
				if (arguments.length === 5) {
					let font = fontStyle + " " + fontSize + "px " + fontName;
					let ctx;
					if (context == null) {
						ctx = new OffscreenCanvas(10, 10).getContext("2d");
						ctx.font = font;
						bounds = this.measureText(text, ctx);
					} else bounds = this.measureText(text, context);
				}
				break;
			}
		}
		return bounds;
	}
	/**
	*
	* @param hexValue - String representing hex value (formatted "0xRRGGBB"
	* i.e. "0xFFFFFF") OR formatted "0xAARRGGBB" i.e. "0x00FFFFFF" for a color
	* with an alpha value I will also put up with "RRGGBB" and "AARRGGBB"
	* without the starting "0x" or "#"
	* @return
	*/
	static getColorFromHexString(hexValue) {
		try {
			if (hexValue == null || hexValue.length === 0) return null;
			let hexOriginal = hexValue;
			let hexAlphabet = "0123456789ABCDEF";
			if (hexValue.charAt(0) === "#") hexValue = hexValue.substring(1);
			if (hexValue.substring(0, 2) === "0x" || hexValue.substring(0, 2) === "0X") hexValue = hexValue.substring(2);
			hexValue = hexValue.toUpperCase();
			let count = hexValue.length;
			let value;
			let k = 0;
			let int1 = 0;
			let int2 = 0;
			if (count === 8 || count === 6) {
				value = new Array(count / 2);
				for (let i = 0; i < count; i += 2) {
					int1 = hexAlphabet.indexOf(hexValue.charAt(i));
					int2 = hexAlphabet.indexOf(hexValue.charAt(i + 1));
					if (int1 === -1 || int2 === -1) {
						ErrorLogger.LogMessage("RendererUtilities", "getColorFromHexString", "Bad hex value: " + hexOriginal, LogLevel.WARNING);
						return null;
					}
					value[k] = int1 * 16 + int2;
					k++;
				}
				if (count === 8) return new Color(value[1], value[2], value[3], value[0]);
				else return new Color(value[0], value[1], value[2]);
			} else ErrorLogger.LogMessage("RendererUtilities", "getColorFromHexString", "Bad hex value: " + hexOriginal, LogLevel.WARNING);
			return null;
		} catch (exc) {
			if (exc instanceof Error) {
				ErrorLogger.LogException("RendererUtilities", "getColorFromHexString", exc);
				return null;
			} else throw exc;
		}
	}
	static getRecommendedTextOutlineWidth() {
		let dpi = RendererSettings.getInstance().getDeviceDPI();
		return Math.max(dpi / 48, 2.5);
	}
	/**
	* For Renderer Use Only
	* Assumes a fresh SVG String from the SVGLookup with its default values
	* @param symbolID
	* @param svg
	* @param strokeColor hex value like "#FF0000";
	* @param fillColor hex value like "#FF0000";
	* @return SVG String
	*/
	static setSVGFrameColors(symbolID, svg, strokeColor, fillColor) {
		let returnSVG;
		let hexStrokeColor;
		let hexFillColor;
		let strokeAlpha = 1;
		let fillAlpha = 1;
		let strokeOpacity = "";
		let fillOpacity = "";
		let ss = SymbolID.getSymbolSet(symbolID);
		SymbolID.getVersion(symbolID);
		let affiliation = SymbolID.getAffiliation(symbolID);
		let defaultFillColor;
		returnSVG = svg;
		if (strokeColor != null) {
			if (strokeColor.getAlpha() !== 255) {
				strokeAlpha = strokeColor.getAlpha() / 255;
				strokeOpacity = " stroke-opacity=\"" + strokeAlpha.toString() + "\"";
				fillOpacity = " fill-opacity=\"" + strokeAlpha.toString() + "\"";
			}
			hexStrokeColor = RendererUtilities.colorToHexString(strokeColor, false);
			returnSVG = svg.replaceAll("stroke=\"#000000\"", "stroke=\"" + hexStrokeColor + "\"" + strokeOpacity);
			returnSVG = returnSVG.replaceAll("fill=\"#000000\"", "fill=\"" + hexStrokeColor + "\"" + fillOpacity);
			if (ss === SymbolID.SymbolSet_LandInstallation || ss === SymbolID.SymbolSet_Space || ss === SymbolID.SymbolSet_CyberSpace || ss === SymbolID.SymbolSet_Activities) {
				let svgStart = "<g id=\"" + SVGLookup.getFrameID(symbolID) + "\">";
				let svgStartReplace = svgStart.substring(0, svgStart.length - 1) + " fill=\"" + hexStrokeColor + "\"" + fillOpacity + ">";
				returnSVG = returnSVG.replace(svgStart, svgStartReplace);
			}
			if (SymbolID.getSymbolSet(symbolID) === SymbolID.SymbolSet_LandInstallation && SymbolID.getFrameShape(symbolID) === "0" || SymbolID.getFrameShape(symbolID) === SymbolID.FrameShape_LandInstallation) {
				let i1 = this.findInstIndIndex(returnSVG) + 5;
				returnSVG = returnSVG.substring(0, i1) + " fill=\"" + hexStrokeColor + "\"" + returnSVG.substring(i1);
			}
		} else if (SymbolID.getSymbolSet(symbolID) === SymbolID.SymbolSet_LandInstallation && SymbolID.getFrameShape(symbolID) === "0" || SymbolID.getFrameShape(symbolID) === SymbolID.FrameShape_LandInstallation) {
			let i1 = this.findInstIndIndex(returnSVG) + 5;
			returnSVG = returnSVG.substring(0, i1) + " fill=\"#000000\"" + returnSVG.substring(i1);
		}
		if (fillColor != null) {
			if (fillColor.getAlpha() !== 255) {
				fillAlpha = fillColor.getAlpha() / 255;
				fillOpacity = " fill-opacity=\"" + fillAlpha.toString() + "\"";
			}
			hexFillColor = RendererUtilities.colorToHexString(fillColor, false);
			switch (affiliation) {
				case SymbolID.StandardIdentity_Affiliation_Friend:
				case SymbolID.StandardIdentity_Affiliation_AssumedFriend:
					defaultFillColor = "fill=\"#80E0FF\"";
					break;
				case SymbolID.StandardIdentity_Affiliation_Hostile_Faker:
					defaultFillColor = "fill=\"#FF8080\"";
					break;
				case SymbolID.StandardIdentity_Affiliation_Suspect_Joker:
					if (SymbolID.getVersion(symbolID) >= SymbolID.Version_2525E) defaultFillColor = "fill=\"#FFE599\"";
					else defaultFillColor = "fill=\"#FF8080\"";
					break;
				case SymbolID.StandardIdentity_Affiliation_Unknown:
				case SymbolID.StandardIdentity_Affiliation_Pending:
					defaultFillColor = "fill=\"#FFFF80\"";
					break;
				case SymbolID.StandardIdentity_Affiliation_Neutral:
					defaultFillColor = "fill=\"#AAFFAA\"";
					break;
				default:
					defaultFillColor = "fill=\"#80E0FF\"";
					break;
			}
			let fillIndex = returnSVG.lastIndexOf(defaultFillColor);
			if (fillIndex != -1) returnSVG = returnSVG.substring(0, fillIndex) + "fill=\"" + hexFillColor + "\"" + fillOpacity + returnSVG.substring(fillIndex + defaultFillColor.length);
		}
		if (returnSVG != null) return returnSVG;
		else return svg;
	}
	/**
	* For Renderer Use Only
	* Changes colors for single point control measures
	* @param symbolID
	* @param svg
	* @param strokeColor hex value like "#FF0000";
	* @param fillColor hex value like "#FF0000";
	* @param isOutline default false; true if this represents a thicker outline to render first beneath the normal symbol (the function must be called twice)
	* @return SVG String
	*
	*/
	static setSVGSPCMColors(symbolID, svg, strokeColor, fillColor, isOutline = false) {
		let returnSVG = svg;
		let hexStrokeColor;
		let hexFillColor;
		let strokeAlpha = 1;
		let fillAlpha = 1;
		let strokeOpacity = "";
		let fillOpacity = "";
		let outlineSize = 15;
		SymbolID.getAffiliation(symbolID);
		let defaultFillColor;
		if (strokeColor != null) {
			if (strokeColor.getAlpha() !== 255) {
				strokeAlpha = strokeColor.getAlpha() / 255;
				strokeOpacity = " stroke-opacity=\"" + strokeAlpha + "\"";
				fillOpacity = " fill-opacity=\"" + strokeAlpha + "\"";
			}
			hexStrokeColor = RendererUtilities.colorToHexString(strokeColor, false);
			let defaultStrokeColor = "#000000";
			if (symbolID.length === 5) {
				if (parseInt(symbolID.substring(2, 4)) >= 13) defaultStrokeColor = "#00A651";
			}
			if (symbolID.length >= 20) {
				if (SymbolUtilities.getBasicSymbolID(symbolID) == "25132100" && SymbolID.getVersion(symbolID) >= SymbolID.Version_2525E) defaultStrokeColor = "#800080";
				else if (isOutline && SymbolUtilities.getBasicSymbolID(symbolID).startsWith("2535")) defaultStrokeColor = "black";
			}
			returnSVG = returnSVG.replaceAll("stroke=\"" + defaultStrokeColor + "\"", "stroke=\"" + hexStrokeColor + "\"" + strokeOpacity);
			returnSVG = returnSVG.replaceAll("fill=\"" + defaultStrokeColor + "\"", "fill=\"" + hexStrokeColor + "\"" + fillOpacity);
		} else strokeColor = Color.BLACK;
		if (isOutline) {
			returnSVG = RendererUtilities.increaseStrokeWidth(returnSVG, outlineSize);
			returnSVG = returnSVG.replace("<g", "<g stroke=\"" + hexStrokeColor + "\" " + strokeOpacity + " stroke-linecap=\"square\"");
		} else {
			let replacement = " fill=\"#" + RendererUtilities.ColorToHex(strokeColor).substring(2) + "\" ";
			returnSVG = returnSVG.replace("fill=\"#000000\"", replacement);
			let topGroupTag = "<g id=\"" + SymbolUtilities.getBasicSymbolID(symbolID) + "\">";
			let newGroupTag = "<g id=\"" + SymbolUtilities.getBasicSymbolID(symbolID) + "\" stroke=\"" + hexStrokeColor + "\"" + strokeOpacity + " " + replacement + ">";
			returnSVG = returnSVG.replace(topGroupTag, newGroupTag);
		}
		if (fillColor != null) {
			if (fillColor.getAlpha() !== 255) {
				fillAlpha = fillColor.getAlpha() / 255;
				fillOpacity = " fill-opacity=\"" + fillAlpha + "\"";
			}
			hexFillColor = RendererUtilities.colorToHexString(fillColor, false);
			defaultFillColor = "fill=\"#000000\"";
			returnSVG = returnSVG.replaceAll(defaultFillColor, "fill=\"" + hexFillColor + "\"" + fillOpacity);
		}
		return returnSVG;
	}
	/**
	* Sets SVG stroke-dasharray when action points are in planned status
	* @param symbolID 
	* @param siIcon 
	* @returns 
	*/
	static setAffiliationDashArray(symbolID, siIcon) {
		let svg = siIcon.getSVG();
		let status = SymbolID.getStatus(symbolID);
		SymbolID.getAffiliation(symbolID);
		let returnVal = siIcon;
		if (status == SymbolID.Status_Planned_Anticipated_Suspect) {
			if (SymbolUtilities.isActionPoint(symbolID)) {
				svg = svg.replace("<rect ", "<rect stroke-dasharray=\"20 19\" ");
				svg = svg.replace("<polygon ", "<polygon stroke-dasharray=\"20 20\" ");
				returnVal = new SVGInfo(siIcon.getID(), siIcon.getBbox(), svg);
			}
		}
		return returnVal;
	}
	static findWidestStrokeWidth(svg) {
		let pattern = RegExp("(stroke-width=\")(\\d+\\.?\\d*)\"", "g");
		let largest = 4;
		let matches = [...svg.matchAll(pattern)];
		for (let match of matches) {
			const width = parseFloat(match[2]);
			if (width > largest) largest = width;
		}
		return largest * RendererUtilities.OUTLINE_SCALING_FACTOR;
	}
	static findInstIndIndex(svg) {
		let start = -1;
		let stop = -1;
		start = svg.indexOf("<rect");
		stop = svg.indexOf(">", start);
		let rect = svg.substring(start, stop + 1);
		if (rect.indexOf("fill") === -1) return start;
		else {
			start = svg.indexOf("<rect", stop);
			stop = svg.indexOf(">", start);
			rect = svg.substring(start, stop + 1);
		}
		return start;
	}
	/**
	* Searches an SVG string and increments all stroke-width values by the increaseBy value.
	* @param svgString The input SVG content as a string.
	* @param increaseBy the number to add to the current stroke value
	* @returns A new SVG string with updated stroke-width values.
	*/
	static increaseStrokeWidth(svgString, increaseBy) {
		let returnVal = svgString.replace(/stroke-width="([\d.]+)"/g, (match, value) => {
			const numericValue = parseFloat(value);
			if (!isNaN(numericValue)) return `stroke-width="${numericValue + increaseBy}"`;
			return match;
		});
		returnVal.indexOf("<g");
		returnVal = returnVal.replace("<g", "<g stroke-width=\"" + increaseBy + "\" ");
		return returnVal;
	}
	static getDistanceBetweenPoints(pt1, pt2) {
		return Math.sqrt(Math.pow(pt2.getX() - pt1.getX(), 2) + Math.pow(pt2.getY() - pt1.getY(), 2));
	}
	/**
	* A starting point for calculating map scale.
	* The User may prefer a different calculation depending on how their maps works.
	* @param mapPixelWidth Width of your map in pixels
	* @param eastLon East Longitude of your map
	* @param westLon West Longitude of your map
	* @param dpi Dots Per Inch of your device.  If not included, will use default renderer value.
	* @return Map scale value to use in the RenderSymbol function {@link armyc2.c5isr.web.render.WebRenderer#RenderSymbol(String, String, String, String, String, String, double, String, Map, Map, int)}
	*/
	static calculateMapScale(mapPixelWidth, eastLon, westLon, dpi = -1) {
		let INCHES_PER_METER = 39.3700787;
		let METERS_PER_DEG = 40075017 / 360;
		try {
			if (dpi < 0) dpi = RendererSettings.getInstance().getDeviceDPI();
			let sizeSquare = Math.abs(eastLon - westLon);
			if (sizeSquare > 180) sizeSquare = 360 - sizeSquare;
			let screenLength = mapPixelWidth / dpi / INCHES_PER_METER;
			return sizeSquare * METERS_PER_DEG / screenLength;
		} catch (e) {
			if (e instanceof Error) ErrorLogger.LogException("RendererUtilities", "calculateMapScale", e, LogLevel.WARNING);
		}
		return 0;
	}
	static scaleIcon(symbolID, icon) {
		let retVal = icon;
		let maxSize = 170;
		let bbox = null;
		if (icon !== null) bbox = icon.getBbox();
		let length = 0;
		if (bbox != null) {
			length = Math.max(bbox.getWidth(), bbox.getHeight());
			if (bbox.getWidth() < 60 && bbox.getHeight() > 90) maxSize = 200;
			if (SVGLookup.getMainIconID(symbolID).length == 8 && length < 145 && length > 0 && bbox.getHeight() < 105 && SymbolID.getCommonModifier1(symbolID) == 0 && SymbolID.getCommonModifier2(symbolID) == 0 && SymbolID.getModifier1(symbolID) == 0 && SymbolID.getModifier2(symbolID) == 0) {
				let ratio = maxSize / length;
				let transx = (bbox.getX() + bbox.getWidth() / 2) * ratio - (bbox.getX() + bbox.getWidth() / 2);
				let transy = (bbox.getY() + bbox.getHeight() / 2) * ratio - (bbox.getY() + bbox.getHeight() / 2);
				let transform = " transform=\"translate(-" + transx + ",-" + transy + ") scale(" + ratio + " " + ratio + ")\">";
				let svg = icon.getSVG();
				svg = svg.replace(">", transform);
				let newBbox = new Rectangle2D(bbox.getX() - transx, bbox.getY() - transy, bbox.getWidth() * ratio, bbox.getHeight() * ratio);
				retVal = new SVGInfo(icon.getID(), newBbox, svg);
			}
		}
		return retVal;
	}
	static async getData(path) {
		const url = path;
		try {
			const response = await fetch(url);
			if (!response.ok) throw new Error(`Response status: ${response.status}`);
			return await response.json();
		} catch (error) {
			if (console && error instanceof Error) console.error(error.message);
			else throw error;
		}
	}
};

