	getMSLInfo(...args) {
		switch (args.length) {
			case 1: {
				const [symbolID] = args;
				let length = symbolID.length;
				if (length >= 20 && length <= 30) {
					let version = SymbolID.getVersion(symbolID);
					return this.getMSLInfo(SymbolUtilities.getBasicSymbolID(symbolID), version);
				} else return null;
			}
			case 2: {
				const [basicID, version] = args;
				let length = basicID.length;
				if (length === 8) if (version == SymbolID.Version_2525E || version == SymbolID.Version_2525Ech1) return MSLookup._MSLookupE.get(basicID);
				else if (version == SymbolID.Version_APP6Ech2 || version == SymbolID.Version_APP6Ech1) return MSLookup._MSLookup6E.get(basicID);
				else if (version == SymbolID.Version_APP6D || version == SymbolID.Version_APP6Dch2) return MSLookup._MSLookup6D.get(basicID);
				else return MSLookup._MSLookupD.get(basicID);
				else if (length >= 20 && length <= 30) return this.getMSLInfo(SymbolUtilities.getBasicSymbolID(basicID), version);
				else return null;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
