//#region src/main/ts/armyc2/c5isr/renderer/utilities/DistanceUnit.ts
/**
* Units of Measure to be used with {@link MilStdAttributes#DistanceUnits}
* Default is meters.
*/
var DistanceUnit = class DistanceUnit {
	static FEET_PER_METER = 3.28084;
	static FLIGHT_LEVEL_PER_METER = .0328084;
	conversionFactor = 0;
	label;
	constructor(conversionFactor, label) {
		this.conversionFactor = conversionFactor;
		this.label = label;
	}
	static parse(distanceUnitText) {
		if (distanceUnitText == null) return null;
		let parts = distanceUnitText.split(",");
		if (parts.length !== 2) return null;
		return new DistanceUnit(parseFloat(parts[0].trim()), parts[1].trim());
	}
	toAttribute() {
		return this.conversionFactor + "," + this.label;
	}
	static METERS = new DistanceUnit(1, "M");
	static FEET = new DistanceUnit(DistanceUnit.FEET_PER_METER, "FT");
	static FLIGHT_LEVEL = new DistanceUnit(DistanceUnit.FLIGHT_LEVEL_PER_METER, "FL");
};

