/**
*
*/
var SectorModUtils = class SectorModUtils {
	static _instance;
	static _initCalled = false;
	static _isReady = false;
	static _sectorMods = /* @__PURE__ */ new Map();
	static _sectorModLists = /* @__PURE__ */ new Map();
	static smd;
	static sme;
	/**
	* 
	* @param url 
	* @deprecated
	*/
	static async setData(url) {}
	constructor() {
		this.init();
	}
	static getInstance() {
		if (!SectorModUtils._instance) SectorModUtils._instance = new SectorModUtils();
		return SectorModUtils._instance;
	}
	isReady() {
		return SectorModUtils._isReady;
	}
	init() {
		try {
			if (SectorModUtils._initCalled != true) {
				SectorModUtils._initCalled = true;
				if (typeof smd_default === "object") SectorModUtils.smd = smd_default;
				if (typeof sme_default === "object") SectorModUtils.sme = sme_default;
				this.loadData(SymbolID.Version_2525Dch1);
				this.loadData(SymbolID.Version_2525Ech1);
			}
		} catch (e) {
			SectorModUtils._isReady = false;
			SectorModUtils._initCalled = false;
			throw e;
		}
		SectorModUtils._isReady = true;
	}
	loadData(version) {
		let ss = -1;
		let l = 0;
		let code = "00";
		let name = "";
		let id = null;
		let sectorList = null;
		let sectorList6 = null;
		let smJSON;
		if (version <= SymbolID.Version_2525Dch1) {
			SymbolID.Version_2525Dch1;
			smJSON = SectorModUtils.smd["smd"]["secmods"];
		} else {
			SymbolID.Version_2525Ech1;
			smJSON = SectorModUtils.sme["sme"]["secmods"];
		}
		try {
			let entry = null;
			for (const modifier of smJSON) if (modifier != null && (modifier["versions"] === void 0 || modifier["versions"] === "")) {
				if (sectorList != null && sectorList.length > 0) {
					let vers = modifier["code"].split(",");
					for (let v of vers) {
						id = v + "-" + ss + "-" + l;
						if (parseInt(v) == SymbolID.Version_2525Ech1 || parseInt(v) == SymbolID.Version_2525Dch1) SectorModUtils._sectorModLists.set(id, sectorList);
						else SectorModUtils._sectorModLists.set(id, sectorList6);
					}
				}
				ss = parseInt(modifier["name"].split(" ")[0]);
				l = parseInt(modifier["category"]);
				sectorList = new Array();
				sectorList6 = new Array();
			} else {
				name = modifier["name"];
				code = modifier["code"];
				if (code.length == 1) code = "0" + code;
				let vers = modifier["versions"].split(",");
				for (let v of vers) {
					id = v + "-" + ss + "-" + l + "-" + code;
					entry = [code, name];
					if (parseInt(v) == SymbolID.Version_2525Ech1 || parseInt(v) == SymbolID.Version_2525Dch1) sectorList.push(entry);
					else sectorList6.push(entry);
					SectorModUtils._sectorMods.set(id, name);
				}
			}
		} catch (e) {
			if (console && e instanceof Error) console.log(e.message);
			else throw e;
		}
	}
	/**
	*
	* @param version like SymbolID.Version_2525Dch1 or SymbolID.Version_2525Ech1  Only tracks sector mods for these 2 versions.
	* @param symbolSet  like SymbolID.SymbolSet_Air; use 0 for Common Modifiers as they are not tied to a symbol set.
	* @param location 1 for top, 2 for bottom
	* @return and ArrayList of String[] like ["00","Unspecified"],["01","Attack/Strike"]
	*/
	getSectorModList(version, symbolSet, location) {
		let ver = version;
		if (version == SymbolID.Version_2525E) ver = SymbolID.Version_2525Ech1;
		if (version == SymbolID.Version_APP6Ech1) ver = SymbolID.Version_APP6Ech2;
		let ss = symbolSet;
		if (ss > 50 && ss < 60) ss = 50;
		let id = ver + "-" + ss + "-" + location;
		if (SectorModUtils._sectorModLists.has(id)) return SectorModUtils._sectorModLists.get(id);
		else {
			let entry = ["00", "Unspecified"];
			let al = new Array();
			al.push(entry);
			return al;
		}
	}
	/**
	*
	* @param version like SymbolID.Version_2525Dch1 or SymbolID.Version_2525Ech1  Only tracks sector mods for these 2 versions.
	* @param symbolSet  like SymbolID.SymbolSet_Air; use 0 for Common Modifiers as they are not tied to a symbol set.
	* @param location 1 for top, 2 for bottom
	* @param code like "01" or "100"
	*/
	getName(version, symbolSet, location, code) {
		let ver = version;
		if (version == SymbolID.Version_2525E) ver = SymbolID.Version_2525Ech1;
		if (version == SymbolID.Version_APP6Ech1) ver = SymbolID.Version_APP6Ech2;
		let ss = symbolSet;
		if (ss > 50 && ss < 60) ss = 50;
		if (ss > 0 && code.length != 2) if (code.length > 2) code = code.substring(0, 2);
		else while (code.length < 2) code = "0" + code;
		else if (ss == 0 && code.length != 3) if (code.length > 3) code = code.substring(0, 3);
		else {
			if (code.startsWith("0")) code = "1" + code;
			while (code.length < 3) code = "0" + code;
		}
		let id = ver + "-" + ss + "-" + location + "-" + code;
		if (SectorModUtils._sectorMods.has(id)) return SectorModUtils._sectorMods.get(id);
		else return "";
	}
};

