/**
*
*
*/
var PathIterator = class PathIterator {
	static SEG_CLOSE = 4;
	static SEG_CUBICTO = 3;
	static SEG_LINETO = 1;
	static SEG_MOVETO = 0;
	static SEG_QUADTO = 2;
	static WIND_EVEN_ODD = 0;
	static WIND_NON_ZERO = 1;
	_currentSeg = 0;
	_pts;
	constructor(tx) {
		this._currentSeg = 0;
		this._pts = new Array();
	}
	getPoints() {
		return this._pts;
	}
	currentSegment(coords) {
		let type = this._pts[this._currentSeg].style;
		if (type === PathIterator.SEG_LINETO || type === PathIterator.SEG_MOVETO) {
			coords[0] = this._pts[this._currentSeg].x;
			coords[1] = this._pts[this._currentSeg].y;
		} else if (type === PathIterator.SEG_CUBICTO) {
			coords[0] = this._pts[this._currentSeg].x;
			coords[1] = this._pts[this._currentSeg].y;
			this._currentSeg++;
			coords[2] = this._pts[this._currentSeg].x;
			coords[3] = this._pts[this._currentSeg].y;
			this._currentSeg++;
			coords[4] = this._pts[this._currentSeg].x;
			coords[5] = this._pts[this._currentSeg].y;
		} else if (type === PathIterator.SEG_QUADTO) {
			coords[0] = this._pts[this._currentSeg].x;
			coords[1] = this._pts[this._currentSeg].y;
			this._currentSeg++;
			coords[2] = this._pts[this._currentSeg].x;
			coords[3] = this._pts[this._currentSeg].y;
		}
		return type;
	}
	getWindingRule() {
		return 1;
	}
	isDone() {
		if (this._currentSeg === this._pts.length) return true;
		return false;
	}
	next() {
		this._currentSeg++;
	}
	reset() {
		this._currentSeg = 0;
	}
	moveTo(x, y) {
		this._pts.push(new POINT2(x, y, PathIterator.SEG_MOVETO));
	}
	lineTo(x, y) {
		this._pts.push(new POINT2(x, y, PathIterator.SEG_LINETO));
	}
	cubicTo(x1, y1, x2, y2, x3, y3) {
		this._pts.push(new POINT2(x1, y1, PathIterator.SEG_CUBICTO));
		this._pts.push(new POINT2(x2, y2, PathIterator.SEG_CUBICTO));
		this._pts.push(new POINT2(x3, y3, PathIterator.SEG_CUBICTO));
	}
	curveTo(x1, y1, x2, y2, x3, y3) {
		this._pts.push(new POINT2(x1, y1, PathIterator.SEG_CUBICTO));
		this._pts.push(new POINT2(x2, y2, PathIterator.SEG_CUBICTO));
		this._pts.push(new POINT2(x3, y3, PathIterator.SEG_CUBICTO));
	}
	quadTo(x1, y1, x2, y2) {
		this._pts.push(new POINT2(x1, y1, PathIterator.SEG_QUADTO));
		this._pts.push(new POINT2(x2, y2, PathIterator.SEG_QUADTO));
	}
	getBounds() {
		let j = 0;
		let left = this._pts[0].x;
		let right = this._pts[0].x;
		let top = this._pts[0].y;
		let bottom = this._pts[0].y;
		let n = this._pts.length;
		for (j = 1; j < n; j++) {
			if (this._pts[j].x < left) left = this._pts[j].x;
			if (this._pts[j].x > right) right = this._pts[j].x;
			if (this._pts[j].y < top) top = this._pts[j].y;
			if (this._pts[j].y > bottom) bottom = this._pts[j].y;
		}
		return new Rectangle2D(left, top, right - left, bottom - top);
	}
	setPathIterator(pts) {
		this.reset();
		this._pts = pts;
	}
};

