/**
*
*
*/
var Shape2 = class extends ShapeInfo {
	constructor(value) {
		super();
		this.setShapeType(value);
		this._Shape = new GeneralPath();
		let stroke = new BasicStroke();
		this.setStroke(stroke);
	}
	style = 0;
	set_Style(value) {
		this.style = value;
	}
	get_Style() {
		return this.style;
	}
	lineTo(pt) {
		this._Shape.lineTo(pt.x, pt.y);
	}
	moveTo(pt) {
		this._Shape.moveTo(pt.x, pt.y);
	}
	getBounds() {
		if (this._Shape instanceof GeneralPath) return this._Shape.getBounds();
		else return this.getBounds();
	}
	getPoints() {
		let points = new Array();
		for (let i = this.getShape().getPathIterator(null); !i.isDone(); i.next()) {
			let coords = new Array(6);
			let type = i.currentSegment(coords);
			switch (type) {
				case IPathIterator.SEG_MOVETO:
				case IPathIterator.SEG_LINETO:
				case IPathIterator.SEG_CLOSE:
					points.push(new POINT2(coords[0], coords[1], type));
					break;
				case IPathIterator.SEG_QUADTO:
					points.push(new POINT2(coords[0], coords[1], type));
					points.push(new POINT2(coords[2], coords[3], type));
					break;
				case IPathIterator.SEG_CUBICTO:
					points.push(new POINT2(coords[0], coords[1], type));
					points.push(new POINT2(coords[2], coords[3], type));
					points.push(new POINT2(coords[4], coords[5], type));
					break;
				default: break;
			}
		}
		return points;
	}
};

