			if (dx <= 0 && dy <= 0) dSign = -1;
			if (dx >= 0 && dy <= 0) dSign = -1;
			if (dx <= 0 && dy >= 0) dSign = 1;
			if (dx >= 0 && dy >= 0) dSign = 1;
