//#region src/main/ts/armyc2/c5isr/JavaLineArray/CChannelPoints2.ts
/**
* A class for channel points used by clsChannelUtility
*
*/
var CChannelPoints2 = class {
	m_Line1;
	m_Line2;
	constructor(...args) {
		switch (args.length) {
			case 0:
				this.m_Line1 = new POINT2();
				this.m_Line2 = new POINT2();
				break;
			case 1: {
				const [pts] = args;
				this.m_Line1 = new POINT2(pts.m_Line1);
				this.m_Line2 = new POINT2(pts.m_Line2);
				break;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
};

