			lDirection.value[0] = -1;
			lLastDirection.value[0] = -1;
			lFlotCount = flot.GetFlotCount2Double(tg, vbPoints2, numPts);
			if (lFlotCount <= 0) return 0;
			style10Points = new Array(lFlotCount);
