	static CalcNewPoint(locx, locY, angle, point, dist) {
		try {
			let m = 0;
			let deltaX = 0;
			let deltaY = 0;
			let dx = 0;
			let dy = 0;
			let nQuadrant = -1;
			if (angle < 0) angle = angle + 360;
			if (angle > 360) angle = angle - 360;
			if (0 <= angle && angle <= 90) {
				nQuadrant = 0;
				angle = 90 - angle;
				angle = Math.abs(angle) * (Math.PI / 180);
			}
			if (90 < angle && angle <= 180) {
				nQuadrant = 1;
				angle = angle - 90;
				angle = Math.abs(angle) * (Math.PI / 180);
			}
			if (180 < angle && angle <= 270) {
				nQuadrant = 2;
				angle = 270 - angle;
				angle = Math.abs(angle) * (Math.PI / 180);
			}
			if (270 < angle && angle <= 360) {
				nQuadrant = 3;
				angle = angle - 270;
				angle = Math.abs(angle) * (Math.PI / 180);
			}
			m = Math.abs(Math.tan(angle));
			deltaX = Math.abs(dist / Math.sqrt(1 + m * m));
			deltaY = Math.abs(m * deltaX);
			switch (nQuadrant) {
				case 0:
					dx = locx + deltaX;
					dy = locY - deltaY;
					break;
				case 1:
					dx = locx + deltaX;
					dy = locY + deltaY;
					break;
				case 2:
					dx = locx - deltaX;
					dy = locY + deltaY;
					break;
				case 3:
					dx = locx - deltaX;
					dy = locY - deltaY;
					break;
				default: break;
			}
			point[0] = dx;
			point[1] = dy;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(flot._className, "CalcNewPoint", new RendererException("Failed inside CalcNewPoint", exc));
			else throw exc;
		}
		return 1;
	}
