			if (segment === 0 && vbPoints[0] < vbPoints[2]) bFlip.value[0] = 0;
			dNum = vbPoints[2 * segment + 3] - vbPoints[2 * segment + 1];
			dDen = vbPoints[2 * segment + 2] - vbPoints[2 * segment];
			if (dDen === 0) dAngle = Math.PI / 2;
			else dAngle = Math.abs(Math.atan(dNum / dDen));
			dAngle = 180 / Math.PI * dAngle;
			if (vbPoints[2 * segment + 0] <= vbPoints[2 * segment + 2] && vbPoints[2 * segment + 1] >= vbPoints[2 * segment + 3]) dAngle = 90 - dAngle;
			else if (vbPoints[2 * segment + 0] <= vbPoints[2 * segment + 2] && vbPoints[2 * segment + 1] <= vbPoints[2 * segment + 3]) dAngle = dAngle + 90;
			else if (vbPoints[2 * segment + 0] >= vbPoints[2 * segment + 2] && vbPoints[2 * segment + 1] <= vbPoints[2 * segment + 3]) dAngle = 270 - dAngle;
			else if (vbPoints[2 * segment + 0] >= vbPoints[2 * segment + 2] && vbPoints[2 * segment + 1] >= vbPoints[2 * segment + 3]) dAngle = 270 + dAngle;
			dDistance = lineutility.CalcDistance2(vbPoints[2 * segment], vbPoints[2 * segment + 1], vbPoints[2 * segment + 2], vbPoints[2 * segment + 3]);
