	/**
	* @deprecated
	* if the line color and fill color are the same or very close then we want to
	* tweak the fill color a bit to make the line appear distinct from the fill.
	* @param tg
	*/
	static tweakFillColor(tg) {
		try {
			if (clsUtility.isSameColor(tg.get_LineColor(), tg.get_FillColor()) === false) return;
			let fillColor = tg.get_FillColor();
			let r = fillColor.getRed();
			let g = fillColor.getGreen();
			let b = fillColor.getBlue();
			let alpha = fillColor.getAlpha();
			r *= .9;
			g *= .9;
			b *= .9;
			alpha *= .8;
			fillColor = new Color(r, g, b, alpha);
			tg.set_FillColor(fillColor);
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(clsUtility._className, "tweakFillColor", new RendererException("Failed inside tweakFillColor", exc));
			else throw exc;
		}
	}
	/**
	* @deprecated
	* Test to see if two colors are similar
	* @param c1
	* @param c2
	* @return true is same (or similar) color
	*/
	static isSameColor(c1, c2) {
		try {
			if (c1 == null || c2 == null) return true;
			let r1 = c1.getRed();
			let r2 = c2.getRed();
			let g1 = c1.getGreen();
			let g2 = c2.getGreen();
			let b1 = c1.getBlue();
			let b2 = c2.getBlue();
			if (Math.abs(r1 - r2) < 5) {
				if (Math.abs(g1 - g2) < 5) {
					if (Math.abs(b1 - b2) < 5) return true;
				}
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(clsUtility._className, "isSameColor", new RendererException("Failed inside isSameColor", exc));
			else throw exc;
		}
		return false;
	}
	/**
	* Customer requested routine for setting the stroke dash pattern
	* Scales dash length with line width and DPI
	* @param width
	* @param style
	* @param cap
	* @param join
	* @return
	*/
	static getLineStroke(width, style, cap, join) {
		let stroke;
		try {
			let dashLength = 2 * width;
			let dotLength = 1;
			let dotSpace = 2 * width;
			switch (style) {
				case 0:
					stroke = new BasicStroke(width, cap, join);
					break;
				case 1:
					stroke = new BasicStroke(width, cap, join, 4, [dashLength, dashLength], 0);
					break;
				case 2:
					stroke = new BasicStroke(width, cap, join, 4, [dotLength, dotSpace], 0);
					break;
				case 3:
					stroke = new BasicStroke(width, cap, join, 4, [
						2 * dashLength,
						dotSpace,
						dotLength,
						dotSpace
					], 0);
					break;
				case 4:
					stroke = new BasicStroke(width, cap, join, 4, [
						dashLength,
						dotSpace,
						dotLength,
						dotSpace,
						dotLength,
						dotSpace
					], 0);
					break;
				default:
					stroke = new BasicStroke(width, cap, join);
					break;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(clsUtility._className, "getLineStroke", new RendererException("Failed inside getLineStroke", exc));
			else throw exc;
		}
		return stroke;
	}
	/**
	* Sets shape properties based on other properties which were set by JavaLineArray
	* @param tg tactical graphic
	* @param shapes the ShapeInfo array
	*/
	static SetShapeProperties(tg, shapes) {
		try {
			if (shapes == null) return;
			let j = 0;
			let shape;
			let stroke;
			let lineThickness = tg.get_LineThickness();
			let lineType = tg.get_LineType();
			clsUtility.LinesWithFill(lineType);
			clsUtility.IsChange1Area(lineType);
			clsUtility.isClosedPolygon(lineType);
			if (tg.get_FillColor() == null) switch (tg.get_LineType()) {
				case TacticalLines.AC:
				case TacticalLines.SAAFR:
				case TacticalLines.MRR:
				case TacticalLines.SL:
				case TacticalLines.TC:
				case TacticalLines.SC:
				case TacticalLines.LLTR:
					shape = shapes[shapes.length - 1];
					shapes.length = 0;
					shapes.push(shape);
					break;
				case TacticalLines.CATK:
				case TacticalLines.AIRAOA:
				case TacticalLines.AAAAA:
				case TacticalLines.SPT:
				case TacticalLines.FRONTAL_ATTACK:
				case TacticalLines.TURNING_MOVEMENT:
				case TacticalLines.MOVEMENT_TO_CONTACT:
				case TacticalLines.MAIN:
				case TacticalLines.CATKBYFIRE: {
					let tempShapes = new Array();
					for (j = 0; j < shapes.length; j++) {
						shape = shapes[j];
						if (shape.getShapeType() !== Shape2.SHAPE_TYPE_FILL) tempShapes.push(shape);
					}
					shapes = tempShapes;
					break;
				}
				default: break;
			}
			for (j = 0; j < shapes.length; j++) {
				shape = shapes[j];
				if (shape == null || shape.getShape() == null) continue;
				if (shape.getShapeType() === Shape2.SHAPE_TYPE_FILL) switch (tg.get_LineType()) {
					case TacticalLines.DEPTH_AREA: break;
					default:
						shape.setFillColor(tg.get_FillColor());
						break;
				}
				clsUtility.ResolveModifierShape(tg, shape);
				if (lineType === TacticalLines.AIRFIELD) {
					if (j === 1) shape.setFillColor(null);
				}
				if (lineType == TacticalLines.BBS_POINT) {
					if (j == 0) shape.setLineColor(null);
				}
				shape.getShapeType();
				tg.get_TexturePaint();
				if (lineThickness === 0) lineThickness = 1;
				stroke = clsUtility.getLineStroke(lineThickness, shape.get_Style(), tg.get_lineCap(), BasicStroke.JOIN_ROUND);
				if (shape.getShapeType() === Shape2.SHAPE_TYPE_FILL) stroke = new BasicStroke(lineThickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_MITER);
				shape.setStroke(stroke);
			}
			if (tg.get_LineType() === TacticalLines.DIRATKAIR) for (let i = 2; i < shapes.length; i++) {
				let arrowHeadShape = shapes[i];
				arrowHeadShape.set_Style(0);
				stroke = clsUtility.getLineStroke(lineThickness, 0, tg.get_lineCap(), BasicStroke.JOIN_ROUND);
				arrowHeadShape.setStroke(stroke);
			}
			else if (tg.get_LineType() === TacticalLines.DIRATKGND || tg.get_LineType() === TacticalLines.DIRATKSPT || tg.get_LineType() == TacticalLines.EXPLOIT || lineType == TacticalLines.INFILTRATION) {
				let arrowHeadShape = shapes[1];
				arrowHeadShape.set_Style(0);
				stroke = clsUtility.getLineStroke(lineThickness, 0, tg.get_lineCap(), BasicStroke.JOIN_ROUND);
				arrowHeadShape.setStroke(stroke);
			} else if (tg.get_LineType() === TacticalLines.PDF) {
				let rectShape = shapes[1];
				rectShape.set_Style(0);
				stroke = clsUtility.getLineStroke(lineThickness, 0, tg.get_lineCap(), BasicStroke.JOIN_ROUND);
				rectShape.setStroke(stroke);
				rectShape.setFillColor(rectShape.getLineColor());
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(clsUtility._className, "SetShapeProperties", new RendererException("Failed inside SetShapeProperties", exc));
			else throw exc;
		}
	}
