	static GetLCPartitions(pixels, LCChannelWith, partitions, singleLinePartitions) {
		try {
			let numPoints = pixels.length / 2;
			let pt0F = new POINT2(0, 0);
			let pt1F = new POINT2(0, 0);
			let pt2F = new POINT2(0, 0);
			let nextP = new P1();
			nextP.start = 0;
			let angles = new Array(numPoints - 1);
			for (let i = 0; i < numPoints - 2; i++) {
				pt0F.x = pixels[2 * i];
				pt0F.y = pixels[2 * i + 1];
				pt1F.x = pixels[2 * i + 2];
				pt1F.y = pixels[2 * i + 3];
				pt2F.x = pixels[2 * i + 4];
				pt2F.y = pixels[2 * i + 5];
				let angle = Math.atan2(pt1F.y - pt0F.y, pt1F.x - pt0F.x) - Math.atan2(pt1F.y - pt2F.y, pt1F.x - pt2F.x);
				let degrees = angle * 180 / Math.PI;
				if (angle < 0) degrees = 360 + degrees;
				if (degrees > 270) {
					let angleTooSmall = false;
					if (lineutility.CalcDistanceDouble(pt0F, pt1F) < lineutility.CalcDistanceDouble(pt1F, pt2F)) {
						let newPt = lineutility.ExtendAlongLineDouble2(pt1F, pt2F, lineutility.CalcDistanceDouble(pt1F, pt0F));
						if (lineutility.CalcDistanceDouble(pt0F, newPt) < LCChannelWith) angleTooSmall = true;
					} else {
						let newPt = lineutility.ExtendAlongLineDouble2(pt1F, pt0F, lineutility.CalcDistanceDouble(pt1F, pt2F));
						if (lineutility.CalcDistanceDouble(pt2F, newPt) < LCChannelWith) angleTooSmall = true;
					}
					if (angleTooSmall) {
						nextP.end_Renamed = i - 1;
						partitions.push(nextP);
						nextP = new P1();
						nextP.start = i;
						nextP.end_Renamed = i + 2;
						singleLinePartitions.push(nextP);
						i++;
						nextP = new P1();
						nextP.start = i + 1;
					}
				} else if (degrees < 90) {
					nextP.end_Renamed = i;
					partitions.push(nextP);
					nextP = new P1();
					nextP.start = i + 1;
				}
				angles[i] = degrees;
			}
			nextP.end_Renamed = numPoints - 2;
			partitions.push(nextP);
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(clsUtility._className, "GetLCPartitions", new RendererException("Failed inside GetLCPartitions", exc));
			else throw exc;
		}
	}
