	/**
	* USAS requires a left-right orientation for ENY, which negates the upper-lower
	* orientation we used for Mil-Std-2525 ENY compliance. Therefore we must reverse
	* the client points for two of the quadrants
	* @param tg tactical graphic
	*/
	static ReverseUSASLCPointsByQuadrant(tg) {
		try {
			if (tg.Pixels.length < 2) return;
			let quadrant = lineutility.GetQuadrantDouble(tg.Pixels[0], tg.Pixels[1]);
			switch (tg.get_LineType()) {
				case TacticalLines.LC:
					if (tg.isHostile()) switch (quadrant) {
						case 2:
						case 3: break;
						case 1:
						case 4: {
							let n = tg.Pixels.length;
							let pts2 = [...tg.Pixels];
							for (let j = 0; j < n; j++) tg.Pixels[j] = pts2[n - j - 1];
							break;
						}
						default:
					}
					else switch (quadrant) {
						case 1:
						case 4: break;
						case 2:
						case 3: {
							let n = tg.Pixels.length;
							let pts2 = [...tg.Pixels];
							for (let j = 0; j < n; j++) tg.Pixels[j] = pts2[n - j - 1];
							break;
						}
						default:
					}
					break;
				default: break;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(clsUtility._className, "ReverseUSASLCPointsByQuadrant", new RendererException("Failed inside ReverseUSASLCPointsByQuadrant", exc));
			else throw exc;
		}
	}
