	/**
	* Calculates the points for Escort.
	*
	* @param points OUT - the client points, also used for the returned points.
	* @param lineType the line type.
	*/
	static GetDISMEscortDouble(tg, points, lineType) {
		let counter = 6;
		try {
			let pt0 = new POINT2(points[1]);
			let pt1 = new POINT2();
			let pt2 = new POINT2();
			let pt3 = new POINT2();
			let pt4 = new POINT2();
			let pt5 = new POINT2(points[2]);
			let offset = points[0];
			let intersect = lineutility.FindClosestPointOnLine(pt0, pt5, offset);
			let xOffset = offset.x - intersect.x;
			let yOffset = offset.y - intersect.y;
			pt1 = new POINT2(pt0.x + xOffset, pt0.y + yOffset);
			pt4 = new POINT2(pt5.x + xOffset, pt5.y + yOffset);
			let pixelSize = tg.getIconSize();
			let distance = lineutility.CalcDistanceDouble(pt1, pt4);
			let center = lineutility.MidPointDouble(pt1, pt4, 0);
			let font = tg.get_Font();
			if (font == null) font = RendererSettings.getInstance().getMPLabelFont();
			let ptCenter = lineutility.MidPointDouble(pt1, pt4, 0);
			if (font.getSize() * 2 + pixelSize < distance) {
				pt2 = lineutility.ExtendAlongLineDouble(center, pt1, pixelSize / 2 + font.getSize());
				pt3 = lineutility.ExtendAlongLineDouble(center, pt4, pixelSize / 2 + font.getSize());
			} else {
				pt2 = ptCenter;
				pt3 = ptCenter;
			}
			pt0.style = 0;
			pt1.style = 1;
			pt2.style = 5;
			pt3.style = 0;
			pt4.style = 1;
			pt5.style = 1;
			points[0] = pt0;
			points[1] = pt1;
			points[2] = pt2;
			points[3] = pt3;
			points[4] = pt4;
			points[5] = pt5;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(DISMSupport._className, "GetDISMEscortDouble", new RendererException("Failed inside GetDISMEscortDouble", exc));
		}
		return counter;
	}
