	static getFDIShape(...args) {
		switch (args.length) {
			case 3: {
				const [tg, ptA, ptC] = args;
				try {
					let midPt = lineutility.MidPointDouble(ptA, ptC, 0);
					let len = lineutility.CalcDistanceDouble(ptA, midPt);
					let ptB = lineutility.ExtendDirectedLine(ptA, ptC, midPt, lineutility.extend_above, len);
					let shape = new Shape2(Shape2.SHAPE_TYPE_POLYLINE);
					shape.moveTo(ptA);
					shape.lineTo(ptB);
					shape.lineTo(ptC);
					shape.set_Style(1);
					shape.setLineColor(tg.get_LineColor());
					let stroke = clsUtility.getLineStroke(tg.get_LineThickness(), shape.get_Style(), BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER);
					shape.setStroke(stroke);
					return shape;
				} catch (exc) {
					if (exc instanceof Error) ErrorLogger.LogException(DISMSupport._className, "getFDIShape", new RendererException("Failed inside getFDIShape", exc));
					else throw exc;
				}
				return null;
			}
			case 4: {
				let [tg, ptA, ptB, ptC] = args;
				try {
					let w = lineutility.CalcDistanceDouble(ptA, ptC) * .25;
					if (w < tg.get_LineThickness() * 1.5) w = tg.get_LineThickness() * 1.5;
					ptC = lineutility.ExtendLineDouble(ptA, ptC, w);
					ptA = lineutility.ExtendLineDouble(ptC, ptA, w);
					let midPt = lineutility.MidPointDouble(ptA, ptC, 0);
					w = lineutility.CalcDistanceDouble(midPt, ptB) * .5;
					if (w < tg.get_LineThickness() * 1.5) w = tg.get_LineThickness() * 1.5;
					ptB = lineutility.ExtendLineDouble(midPt, ptB, w);
					let shape = new Shape2(Shape2.SHAPE_TYPE_POLYLINE);
					shape.moveTo(ptA);
					shape.lineTo(ptB);
					shape.lineTo(ptC);
					shape.set_Style(1);
					shape.setLineColor(tg.get_LineColor());
					let stroke = clsUtility.getLineStroke(tg.get_LineThickness(), shape.get_Style(), BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER);
					shape.setStroke(stroke);
					return shape;
				} catch (exc) {
					if (exc instanceof Error) ErrorLogger.LogException(DISMSupport._className, "getFDIShape", new RendererException("Failed inside getFDIShape", exc));
					else throw exc;
				}
				return null;
			}
			default: throw Error(`Invalid number of arguments`);
		}
	}
