			dDeltaXAlong = Math.cos(dAngle1) * dJaggyHalfPeriod;
			dDeltaYAlong = Math.sin(dAngle1) * dJaggyHalfPeriod;
			iNumJaggies = Math.trunc(dLength / dJaggyHalfPeriod) - 3;
			i = 2;
