			let midpt = new POINT2();
			let savepoints = new Array(3);
			let j = 0;
			let d = 0;
			for (j = 0; j < 3; j++) savepoints[j] = new POINT2(points[j]);
			lineutility.InitializePOINT2Array(arrowpts);
			points[0].x = savepoints[0].x;
			points[0].y = savepoints[0].y;
