	/**
	* Calculates the points for LINTGT
	*
	* @param points - OUT - the client points, also used for the returned points.
	* @param linetype the line type.
	* @param vblCounter the number of points required to display the symbol
	*/
	static GetDISMLinearTargetDouble(points, linetype, vblCounter) {
		let counter = 0;
		try {
			let j = 0;
			let dMBR = lineutility.MBRDistance(points, vblCounter - 4);
			let DPIScaleFactor = RendererSettings.getInstance().getDeviceDPI() / 96;
			if (dMBR / 20 > DISMSupport.maxLength * DPIScaleFactor) dMBR = 20 * DISMSupport.maxLength * DPIScaleFactor;
			if (dMBR / 20 < DISMSupport.minLength * DPIScaleFactor) dMBR = 20 * DISMSupport.minLength * DPIScaleFactor;
			if (dMBR < 150 * DPIScaleFactor) dMBR = 150 * DPIScaleFactor;
			if (dMBR > 250 * DPIScaleFactor) dMBR = 250 * DPIScaleFactor;
			for (j = 0; j < vblCounter - 4; j++) {
				points[counter].style = 0;
				counter++;
			}
			points[counter - 1].style = 5;
			points[counter] = lineutility.ExtendTrueLinePerpDouble(points[0], points[1], points[0], dMBR / 20, 0);
			counter++;
			points[counter] = lineutility.ExtendTrueLinePerpDouble(points[0], points[1], points[0], -dMBR / 20, 5);
			counter++;
			points[counter] = lineutility.ExtendTrueLinePerpDouble(points[vblCounter - 5], points[vblCounter - 6], points[vblCounter - 5], dMBR / 20, 0);
			counter++;
			points[counter] = lineutility.ExtendTrueLinePerpDouble(points[vblCounter - 5], points[vblCounter - 6], points[vblCounter - 5], -dMBR / 20, 5);
			counter++;
			if (linetype === TacticalLines.FPF) points[0].style = 6;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(DISMSupport._className, "GetDISMLinearTargetDouble", new RendererException("Failed inside GetDISMLinearTargetDouble", exc));
			else throw exc;
		}
		return counter;
	}
