//#region src/main/ts/armyc2/c5isr/JavaLineArray/countsupport.ts
/**
* A class to calculate the number of pixels based points required for a line
*
*/
var countsupport = class countsupport {
	static maxLength = 100;
	static minLength = 2.5;
	static _className = "countsupport";
	/**
	* The main function to return the number of points needed for a symbol
	* @param vblCounter the number of client points
	* @param pLinePoints the client point array
	* @return the number of points required to draw the symbol
	*/
	static GetCountersDouble(tg, vblCounter, pLinePoints, clipBounds) {
		let count = 0;
		try {
			let vbiDrawThis = tg.get_LineType();
			let j = 0;
			let vblSaveCounter = vblCounter;
			let pSquarePoints = new Array(4);
			let pUpperLinePoints;
			let pLowerLinePoints;
			let dRadius = 0;
			let pointsCorner = new Array(2);
			pUpperLinePoints = new Array(vblCounter);
			pLowerLinePoints = new Array(vblCounter);
			for (j = 0; j < vblCounter; j++) {
				pUpperLinePoints[j] = new POINT2(pLinePoints[j]);
				pLowerLinePoints[j] = new POINT2(pLinePoints[j]);
			}
			lineutility.InitializePOINT2Array(pointsCorner);
			lineutility.InitializePOINT2Array(pSquarePoints);
			switch (vbiDrawThis) {
				case TacticalLines.BS_ELLIPSE:
					count = 37;
					break;
				case TacticalLines.BS_CROSS:
					count = 4;
					break;
				case TacticalLines.OVERHEAD_WIRE:
					count = vblCounter * 15;
					break;
				case TacticalLines.REEF:
					vblCounter = countsupport.GetReefCount(pLinePoints, arraysupport.getScaledSize(40, tg.get_LineThickness(), tg.get_patternScale()), vblSaveCounter);
					count = vblCounter;
					break;
				case TacticalLines.RESTRICTED_AREA:
					vblCounter = countsupport.GetRestrictedAreaCount(pLinePoints, arraysupport.getScaledSize(15, tg.get_LineThickness(), tg.get_patternScale()), vblSaveCounter);
					count = vblCounter;
					break;
				case TacticalLines.TRAINING_AREA:
					vblCounter += 30;
					count = vblCounter;
					break;
				case TacticalLines.PIPE:
					count = countsupport.GetPipeCount(pLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblSaveCounter);
					break;
				case TacticalLines.ANCHORAGE_AREA:
				case TacticalLines.ANCHORAGE_LINE:
					count = flot.GetAnchorageCountDouble(pLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					break;
				case TacticalLines.LRO:
					count = countsupport.GetXPointsCount(pLinePoints, arraysupport.getScaledSize(30, tg.get_LineThickness(), tg.get_patternScale()), vblCounter) + countsupport.GetLVOCount(pLinePoints, arraysupport.getScaledSize(30, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					break;
				case TacticalLines.LVO:
					count = countsupport.GetLVOCount(pLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					break;
				case TacticalLines.ICING:
					vblCounter = countsupport.GetIcingCount(pLinePoints, arraysupport.getScaledSize(15, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					count = vblCounter;
					break;
				case TacticalLines.FLOT:
					vblSaveCounter = vblCounter;
					vblCounter = flot.GetFlotCountDouble(pLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					count = vblCounter;
					break;
				case TacticalLines.MVFR:
				case TacticalLines.UNDERCAST:
					vblSaveCounter = vblCounter;
					vblCounter = flot.GetFlotCountDouble(pLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					count = vblCounter;
					break;
				case TacticalLines.ITD:
					vblCounter = countsupport.GetITDQty(pLinePoints, arraysupport.getScaledSize(15, tg.get_LineThickness(), tg.get_patternScale()), vblCounter) + vblCounter;
					count = vblCounter;
					break;
				case TacticalLines.CONVERGENCE:
					vblCounter = countsupport.GetConvergenceQty(pLinePoints, arraysupport.getScaledSize(10, tg.get_LineThickness(), tg.get_patternScale()), vblCounter) + vblCounter;
					count = vblCounter;
					break;
				case TacticalLines.RIDGE:
					vblCounter = countsupport.GetFORTLCountDouble(tg, pLinePoints, vblSaveCounter);
					count = vblCounter;
					break;
				case TacticalLines.TROUGH:
				case TacticalLines.UPPER_TROUGH:
				case TacticalLines.INSTABILITY:
				case TacticalLines.SHEAR:
					vblCounter = countsupport.GetSquallQty(pLinePoints, 6, arraysupport.getScaledSize(30, tg.get_LineThickness(), tg.get_patternScale()), vblSaveCounter);
					count = vblCounter;
					break;
				case TacticalLines.CABLE:
					vblCounter = countsupport.GetSquallQty(pLinePoints, 6, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblSaveCounter);
					count = vblCounter;
					break;
				case TacticalLines.SQUALL:
					vblCounter = countsupport.GetSquallQty(pLinePoints, 5, arraysupport.getScaledSize(30, tg.get_LineThickness(), tg.get_patternScale()), vblSaveCounter) + 2 * vblSaveCounter;
					count = vblCounter;
					break;
				case TacticalLines.USF:
				case TacticalLines.SFG:
				case TacticalLines.SFY:
				case TacticalLines.SF:
					vblCounter = flot.GetSFCountDouble(pLinePoints, vblCounter);
					count = vblCounter;
					break;
				case TacticalLines.OFY:
					vblSaveCounter = vblCounter;
					vblCounter = flot.GetOFYCountDouble(pLinePoints, arraysupport.getScaledSize(80, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					count = vblCounter;
					break;
				case TacticalLines.UCF:
				case TacticalLines.CF:
				case TacticalLines.CFG:
				case TacticalLines.CFY:
					count = countsupport.GetFORTLCountDouble(tg, pLinePoints, vblSaveCounter);
					count += vblSaveCounter;
					break;
				case TacticalLines.FOLLA:
				case TacticalLines.FOLSP:
					count = 16;
					break;
				case TacticalLines.ROADBLK:
				case TacticalLines.FERRY:
				case TacticalLines.EXPLOIT:
					count = 8;
					break;
				case TacticalLines.NAVIGATION:
				case TacticalLines.IL:
				case TacticalLines.PLANNED:
				case TacticalLines.ESR1:
				case TacticalLines.ESR2:
				case TacticalLines.FORDSITE:
				case TacticalLines.FOXHOLE:
				case TacticalLines.DECEIVE:
					count = 4;
					break;
				case TacticalLines.AMBUSH:
					count = 53;
					break;
				case TacticalLines.CLUSTER:
					count = 28;
					break;
				case TacticalLines.CONTAIN:
					count = 40;
					break;
				case TacticalLines.BYIMP:
					count = 18;
					break;
				case TacticalLines.SPTBYFIRE:
					count = 16;
					break;
				case TacticalLines.BLOCK:
				case TacticalLines.MNFLDBLK:
					count = 4;
					break;
				case TacticalLines.PAA_RECTANGULAR:
					count = 5;
					break;
				case TacticalLines.RECTANGULAR_TARGET:
					count = 9;
					break;
				case TacticalLines.PENETRATE:
					count = 7;
					break;
				case TacticalLines.ASLTXING:
				case TacticalLines.GAP:
				case TacticalLines.BYPASS:
				case TacticalLines.EASY:
				case TacticalLines.BREACH:
				case TacticalLines.CANALIZE:
					count = 12;
					break;
				case TacticalLines.MNFLDDIS:
					count = 22;
					break;
				case TacticalLines.WITHDRAW:
				case TacticalLines.DISENGAGE:
				case TacticalLines.WDRAWUP:
				case TacticalLines.DELAY:
				case TacticalLines.RETIRE:
				case TacticalLines.FPOL:
				case TacticalLines.RPOL:
				case TacticalLines.ENVELOPMENT:
					count = 23;
					break;
				case TacticalLines.PURSUIT:
					count = 25;
					break;
				case TacticalLines.SEIZE:
				case TacticalLines.CAPTURE:
				case TacticalLines.EVACUATE:
					count = 37;
					break;
				case TacticalLines.RIP:
				case TacticalLines.DEMONSTRATE:
					count = 29;
					break;
				case TacticalLines.MOBILE_DEFENSE:
					count = 44;
					break;
				case TacticalLines.DIRATKSPT:
					count = vblCounter + 3;
					break;
				case TacticalLines.EXFILTRATION:
				case TacticalLines.INFILTRATION:
					count = vblCounter + 10 + 3;
					break;
				case TacticalLines.ABATIS:
					count = vblCounter + 3;
					break;
				case TacticalLines.FPF:
				case TacticalLines.LINTGT:
				case TacticalLines.LINTGTS:
					count = vblCounter + 4;
					break;
				case TacticalLines.CHANNEL:
				case TacticalLines.CHANNEL_FLARED:
				case TacticalLines.CHANNEL_DASHED:
					count = 2 * vblCounter;
					break;
				case TacticalLines.SARA:
					count = 16;
					break;
				case TacticalLines.COVER:
				case TacticalLines.SCREEN:
				case TacticalLines.GUARD:
				case TacticalLines.PDF:
				case TacticalLines.ATKBYFIRE:
					count = 14;
					break;
				case TacticalLines.ESCORT:
					count = 6;
					break;
				case TacticalLines.RAFT:
				case TacticalLines.MFLANE:
					count = 8;
					break;
				case TacticalLines.DIRATKGND:
					count = vblCounter + 10;
					break;
				case TacticalLines.DIRATKAIR:
					count = vblCounter + 9;
					break;
				case TacticalLines.DISRUPT:
				case TacticalLines.CLEAR:
					count = 20;
					break;
				case TacticalLines.MSDZ:
					count = 300;
					break;
				case TacticalLines.CONVOY:
				case TacticalLines.HCONVOY:
					count = 10;
					break;
				case TacticalLines.ISOLATE:
				case TacticalLines.CORDONKNOCK:
				case TacticalLines.CORDONSEARCH:
				case TacticalLines.DENY:
					count = 50;
					break;
				case TacticalLines.AREA_DEFENSE:
					count = 67;
					break;
				case TacticalLines.OCCUPY:
				case TacticalLines.CONTROL:
				case TacticalLines.LOCATE:
					count = 32;
					break;
				case TacticalLines.SECURE:
					count = 29;
					break;
				case TacticalLines.RETAIN:
					count = 75;
					break;
				case TacticalLines.TURN_REVD:
				case TacticalLines.TURN:
					count = 29;
					break;
				case TacticalLines.AIRFIELD:
					count = vblCounter + 5;
					break;
				case TacticalLines.FENCED:
					count = vblCounter;
					break;
				case TacticalLines.MSR_ALT:
				case TacticalLines.ASR_ALT:
				case TacticalLines.TRAFFIC_ROUTE_ALT:
					count = vblCounter * 9;
					break;
				case TacticalLines.MSR_TWOWAY:
				case TacticalLines.ASR_TWOWAY:
					count = vblCounter * 11;
					break;
				case TacticalLines.MSR_ONEWAY:
				case TacticalLines.ASR_ONEWAY:
				case TacticalLines.TRAFFIC_ROUTE_ONEWAY:
					count = vblCounter * 6;
					break;
				case TacticalLines.WF:
				case TacticalLines.UWF:
					vblCounter = flot.GetFlotCount2Double(tg, pLinePoints, vblCounter);
					vblCounter += vblSaveCounter;
					count = vblCounter;
					break;
				case TacticalLines.WFG:
				case TacticalLines.WFY:
					vblCounter = flot.GetFlotCount2Double(tg, pLinePoints, vblCounter);
					count = vblCounter;
					break;
				case TacticalLines.FORDIF: {
					dRadius = lineutility.CalcDistanceToLineDouble(pLinePoints[0], pLinePoints[1], pLinePoints[2]);
					let spikeLength = arraysupport.getScaledSize(10, tg.get_LineThickness(), tg.get_patternScale());
					count = Math.trunc(dRadius / (spikeLength / 2) * 3) + 6;
					if (clipBounds != null) {
						let width = clipBounds.getWidth();
						let height = clipBounds.getHeight();
						dRadius = Math.sqrt(width * width + height * height);
						count = Math.trunc(dRadius / (spikeLength / 2)) + 6;
					}
					break;
				}
				case TacticalLines.ATDITCH:
				case TacticalLines.ATDITCHC:
				case TacticalLines.ATDITCHM:
					count = countsupport.GetDitchCountDouble(pLinePoints, vblSaveCounter, vbiDrawThis);
					break;
				case TacticalLines.CATK:
				case TacticalLines.MAIN:
				case TacticalLines.MAIN_STRAIGHT:
				case TacticalLines.AIRAOA:
				case TacticalLines.SPT:
				case TacticalLines.SPT_STRAIGHT:
					count = 2 * vblCounter + 8;
					break;
				case TacticalLines.FRONTAL_ATTACK:
					count = 2 * vblCounter + 15;
					break;
				case TacticalLines.TURNING_MOVEMENT:
					count = 2 * vblCounter + 14;
					break;
				case TacticalLines.MOVEMENT_TO_CONTACT:
					count = 2 * vblCounter + 24;
					break;
				case TacticalLines.CATKBYFIRE:
					count = 2 * vblCounter + 17;
					break;
				case TacticalLines.AAAAA:
					count = 2 * vblCounter + 19;
					break;
				case TacticalLines.LLTR:
				case TacticalLines.SAAFR:
				case TacticalLines.AC:
				case TacticalLines.SC:
				case TacticalLines.MRR:
				case TacticalLines.SL:
				case TacticalLines.TC:
					vblCounter = 6 * (vblSaveCounter - 1);
					count = vblCounter + 26 * vblSaveCounter * 2;
					break;
				case TacticalLines.ATWALL:
				case TacticalLines.LINE:
				case TacticalLines.OBSAREA:
				case TacticalLines.OBSFAREA:
				case TacticalLines.STRONG:
				case TacticalLines.ZONE:
				case TacticalLines.ENCIRCLE:
				case TacticalLines.FORT_REVD:
				case TacticalLines.FORT:
				case TacticalLines.FORTL:
					count = countsupport.GetFORTLCountDouble(tg, pLinePoints, vblSaveCounter);
					break;
				case TacticalLines.TRIPLE:
				case TacticalLines.DOUBLEC:
				case TacticalLines.SINGLEC:
				case TacticalLines.HWFENCE:
				case TacticalLines.LWFENCE:
				case TacticalLines.UNSP:
				case TacticalLines.DOUBLEA:
				case TacticalLines.SFENCE:
				case TacticalLines.DFENCE:
					count = Channels.GetTripleCountDouble(pLinePoints, vblCounter, vbiDrawThis);
					break;
				case TacticalLines.BBS_LINE:
					count = 2 * vblCounter;
					break;
				case TacticalLines.LC:
					pUpperLinePoints = Channels.GetChannelArray2Double(1, pUpperLinePoints, 1, vblCounter, vbiDrawThis, Math.trunc(arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale())));
					pLowerLinePoints = Channels.GetChannelArray2Double(1, pLowerLinePoints, 0, vblCounter, vbiDrawThis, Math.trunc(arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale())));
					count = flot.GetFlotCountDouble(pUpperLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblCounter) + flot.GetFlotCountDouble(pLowerLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), vblCounter);
					break;
				case TacticalLines.OCCLUDED:
				case TacticalLines.UOF:
					vblSaveCounter = vblCounter;
					vblCounter = flot.GetOccludedCountDouble(pLinePoints, vblCounter);
					vblCounter += vblSaveCounter;
					count = vblCounter;
					break;
				case TacticalLines.FIX:
				case TacticalLines.MNFLDFIX:
					if (pLinePoints.length > 1) count = countsupport.GetDISMFixCountDouble(pLinePoints[0], pLinePoints[1], clipBounds);
					else count = 0;
					break;
				case TacticalLines.BYDIF:
					if (clipBounds != null) {
						countsupport.GetByDifSegment(pLinePoints, pointsCorner);
						let ul = new POINT2(clipBounds.getMinX(), clipBounds.getMinY());
						let lr = new POINT2(clipBounds.getMaxX(), clipBounds.getMaxY());
						let ptsCorner = lineutility.BoundOneSegment(pointsCorner[0], pointsCorner[1], ul, lr);
						if (ptsCorner != null) count = countsupport.GetDISMFixCountDouble(ptsCorner[0], ptsCorner[1], clipBounds);
						else count = 20;
					} else count = countsupport.GetDISMFixCountDouble(pLinePoints[0], pLinePoints[1], clipBounds);
					break;
				default:
					count = vblCounter;
					break;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetCountersDouble", new RendererException("Failed inside GetCountersDouble " + tg.get_LineType().toString(), exc));
			else throw exc;
		}
		return Math.trunc(count);
	}
	static GetReefCount(pLinePoints, length, vblCounter) {
		let count = 0;
		try {
			let d = 0;
			for (let j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				count += 5 * Math.trunc(d / length);
			}
			count += 2 * vblCounter;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetReefCount", new RendererException("Failed inside GetReefCount", exc));
			else throw exc;
		}
		return count;
	}
	static GetRestrictedAreaCount(pLinePoints, length, vblCounter) {
		let count = 0;
		try {
			let d = 0;
			for (let j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				count += 4 * Math.trunc(d / length);
			}
			count += 2 * vblCounter;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetRestrictedAreaCount", new RendererException("Failed inside GetRestrictedAreaCount", exc));
			else throw exc;
		}
		return count;
	}
	static GetPipeCount(pLinePoints, length, vblCounter) {
		let count = 0;
		try {
			let d = 0;
			for (let j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				count += 3 * Math.trunc(d / length);
			}
			count += 2 * vblCounter;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetPipeCount", new RendererException("Failed inside GetPipeCount", exc));
			else throw exc;
		}
		return count;
	}
	static GetXPointsCount(pOriginalLinePoints, segmentLength, vblCounter) {
		let xCounter = 0;
		try {
			let j = 0;
			let d = 0;
			let numThisSegment = 0;
			for (j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pOriginalLinePoints[j], pOriginalLinePoints[j + 1]);
				numThisSegment = Math.trunc((d - segmentLength / 2) / segmentLength);
				xCounter += 4 * numThisSegment;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetXPointsCount", new RendererException("Failed inside GetXPointsCount", exc));
			else throw exc;
		}
		return xCounter;
	}
	static GetLVOCount(pOriginalLinePoints, segmentLength, vblCounter) {
		let lEllipseCounter = 0;
		try {
			let d = 0;
			let lHowManyThisSegment = 0;
			let j = 0;
			for (j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pOriginalLinePoints[j], pOriginalLinePoints[j + 1]);
				lHowManyThisSegment = Math.trunc((d - segmentLength) / segmentLength) + 1;
				lEllipseCounter += lHowManyThisSegment * 37;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetLVOCount", new RendererException("Failed inside GetLVOCount", exc));
			else throw exc;
		}
		return lEllipseCounter;
	}
	static GetIcingCount(points, length, vblCounter) {
		let total = 2 * vblCounter;
		try {
			let d = 0;
			for (let j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(points[j], points[j + 1]);
				d = d / length * 4;
				total += d;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetIcingCount", new RendererException("Failed inside GetIcingCount", exc));
			else throw exc;
		}
		return total;
	}
	static GetITDQty(pLinePoints, length, vblCounter) {
		let total = 0;
		try {
			let j = 0;
			let d = 0;
			let n = 0;
			for (j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				n = 2 * Math.trunc(d / length);
				if (n < 2) n = 2;
				total += n;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetITDQty", new RendererException("Failed inside GetITDQty", exc));
			else throw exc;
		}
		return total;
	}
	static GetConvergenceQty(pLinePoints, length, vblCounter) {
		let total = vblCounter;
		try {
			let j = 0;
			let d = 0;
			for (j = 0; j < vblCounter - 1; j++) {
				d = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				total += 4 * Math.trunc(d / length);
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetConvergenceQty", new RendererException("Failed inside GetConvergenceQty", exc));
			else throw exc;
		}
		return total;
	}
	/**
	* Calculates the points for ATDITCH, ATDITCHC, ATDITCHM
	* @param pLinePoints the client point array
	* @param vblCounter the number of client points
	* @param vbiDrawThis the line type
	* @return
	*/
	static GetDitchCountDouble(pLinePoints, vblCounter, vbiDrawThis) {
		let vblXCounter = 0;
		try {
			let j = 0;
			let nHowManyThisSegment = 0;
			let dHowFar = 0;
			vblXCounter = vblCounter;
			for (j = 0; j < vblCounter - 1; j++) {
				dHowFar = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				nHowManyThisSegment = Math.trunc((dHowFar - 1) / 12);
				if (dHowFar > 24) switch (vbiDrawThis) {
					case TacticalLines.ATDITCHM:
						vblXCounter += 5 * nHowManyThisSegment + 1;
						break;
					default:
						vblXCounter += 4 * nHowManyThisSegment;
						break;
				}
				else vblXCounter += 2;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetDitchcountDouble", new RendererException("Failed inside GetDitchCountDouble " + vbiDrawThis.toString(), exc));
			else throw exc;
		}
		return vblXCounter;
	}
	static GetSquallQty(pLinePoints, quantity, length, numPoints) {
		let counter = 0;
		try {
			let j = 0;
			let dist = 0;
			let numCurves = 0;
			for (j = 0; j < numPoints - 1; j++) {
				dist = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				numCurves = Math.trunc(dist / length);
				counter += numCurves * quantity;
				if (numCurves === 0) counter += 2;
			}
			if (counter < numPoints) counter = numPoints;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetSquallQty", new RendererException("Failed inside GetSquallQty", exc));
			else throw exc;
		}
		return counter;
	}
	static GetSquallSegQty(StartPt, EndPt, quantity, length) {
		let qty = 0;
		try {
			let dist = lineutility.CalcDistanceDouble(StartPt, EndPt);
			qty = Math.trunc(dist / length) * quantity;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetSquallSegQty", new RendererException("Failed inside GetSquallSegQty", exc));
			else throw exc;
		}
		return qty;
	}
	/**
	* returns number of points required for ATWALL, FORT and other symbols
	* @param pLinePoints the client points
	* @param vblCounter the number of client points
	* @return
	*/
	static GetFORTLCountDouble(tg, pLinePoints, vblCounter) {
		let lCounter = 0;
		try {
			let j = 0;
			let dCounter = 0;
			let dIncrement = 0;
			switch (tg.get_LineType()) {
				case TacticalLines.UCF:
				case TacticalLines.CF:
				case TacticalLines.CFG:
				case TacticalLines.CFY:
					dIncrement = arraysupport.getScaledSize(60, tg.get_LineThickness(), tg.get_patternScale());
					break;
				case TacticalLines.RIDGE:
					dIncrement = arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale());
					break;
				default:
					dIncrement = arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale());
					break;
			}
			for (j = 0; j < vblCounter - 1; j++) {
				dCounter = lineutility.CalcDistanceDouble(pLinePoints[j], pLinePoints[j + 1]);
				switch (tg.get_LineType()) {
					case TacticalLines.CFG:
						dCounter = dCounter / dIncrement * 13;
						break;
					case TacticalLines.CFY:
						dCounter = dCounter / dIncrement * 17;
						break;
					default:
						dCounter = dCounter / dIncrement * 10;
						break;
				}
				if (dCounter < 4) dCounter = 4;
				lCounter += Math.trunc(dCounter);
			}
			lCounter += 10 + vblCounter;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetFORTLCountDouble", new RendererException("Failed inside GetFORTLCountDouble", exc));
			else throw exc;
		}
		return lCounter;
	}
	static GetByDifSegment(points, pointsCorner) {
		try {
			let point_mid = new POINT2();
			if (pointsCorner == null) {
				pointsCorner = new Array(2);
				lineutility.InitializePOINT2Array(pointsCorner);
			}
			point_mid.x = (points[0].x + points[1].x) / 2;
			point_mid.y = (points[0].y + points[1].y) / 2;
			pointsCorner[0].x = points[0].x - point_mid.x + points[2].x;
			pointsCorner[0].y = points[0].y - point_mid.y + points[2].y;
			pointsCorner[1].x = points[1].x - point_mid.x + points[2].x;
			pointsCorner[1].y = points[1].y - point_mid.y + points[2].y;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetByDifSegment", new RendererException("Failed inside GetByDifSegment", exc));
			else throw exc;
		}
	}
	/**
	* clipBounds is used because of the glyphs on one segment
	* @param FirstLinePoint
	* @param LastLinePoint
	* @param clipBounds
	* @return
	*/
	static GetDISMFixCountDouble(FirstLinePoint, LastLinePoint, clipBounds) {
		let counter = 0;
		try {
			let savepoints = new Array(2);
			let dLength = 0;
			let dJaggyHalfAmp = 0;
			let dJaggyHalfPeriod = 0;
			let iNumJaggies = 0;
			savepoints[0] = new POINT2(FirstLinePoint);
			savepoints[1] = new POINT2(LastLinePoint);
			if (clipBounds != null) {
				let ul = new POINT2(clipBounds.getMinX(), clipBounds.getMinY());
				let lr = new POINT2(clipBounds.getMaxX(), clipBounds.getMaxY());
				savepoints = lineutility.BoundOneSegment(FirstLinePoint, LastLinePoint, ul, lr);
			}
			if (savepoints == null) return 0;
			dLength = Math.sqrt((savepoints[1].x - savepoints[0].x) * (savepoints[1].x - savepoints[0].x) + (savepoints[1].y - savepoints[0].y) * (savepoints[1].y - savepoints[0].y));
			dJaggyHalfAmp = dLength / 15;
			let DPIScaleFactor = RendererSettings.getInstance().getDeviceDPI() / 96;
			if (dJaggyHalfAmp > countsupport.maxLength * DPIScaleFactor) dJaggyHalfAmp = countsupport.maxLength * DPIScaleFactor;
			if (dJaggyHalfAmp < countsupport.minLength * DPIScaleFactor) dJaggyHalfAmp = countsupport.minLength * DPIScaleFactor;
			dJaggyHalfPeriod = dJaggyHalfAmp / 1.5;
			iNumJaggies = Math.trunc(dLength / dJaggyHalfPeriod) - 3;
			if (iNumJaggies < 0) iNumJaggies = 0;
			savepoints = null;
			counter = 20 + iNumJaggies * 3;
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(countsupport._className, "GetDISMFixCount", new RendererException("Failed inside GetDISMFixCount", exc));
			else throw exc;
		}
		return counter;
	}
};

//#endregion
//#region src/main/ts/armyc2/c5isr/JavaLineArray/CELineArray.ts
/**
* A class for the interface between the points calculation CELineArray and
* the tactical renderer.
*
*
*/
var CELineArray = class CELineArray {
	static _className = "CELineArray";
	/**
	* public function to return the line count required for all of the symbols
	*
	* @param plArrayOfLongs the client points as an array of POINT2 in pixels.
	* @param lElements the number of client points.
	* @param ChannelWidth the chanel width in pixels
	*
	* @return the number of points which will be required for the symbol.
	*/
	static CGetLineCountDouble(tg, plArrayOfLongs, lElements, ChannelWidth) {
		let lResult = 0;
		try {
			let lPtrcntr = 0;
			let lLowerFlotCount = 0;
			let lUpperFlotCount = 0;
			let pLinePoints = new Array(lElements);
			let pLowerLinePoints = new Array(lElements);
			let pUpperLinePoints = new Array(lElements);
			new Array(2 * lElements + 2);
			let i = 0;
			if (lElements <= 0) return -1;
			lineutility.InitializePOINT2Array(pLinePoints);
			lineutility.InitializePOINT2Array(pUpperLinePoints);
			lineutility.InitializePOINT2Array(pLowerLinePoints);
			for (i = 0; i < lElements; i++) {
				pLinePoints[i].x = plArrayOfLongs[lPtrcntr];
				lPtrcntr++;
				pLinePoints[i].y = plArrayOfLongs[lPtrcntr];
				lPtrcntr++;
			}
			for (i = 0; i < lElements; i++) {
				pLowerLinePoints[i] = new POINT2(pLinePoints[i]);
				pUpperLinePoints[i] = new POINT2(pLinePoints[i]);
			}
			switch (tg.get_LineType()) {
				case TacticalLines.CHANNEL:
				case TacticalLines.CHANNEL_FLARED:
				case TacticalLines.CHANNEL_DASHED:
					lResult = 2 * lElements;
					break;
				case TacticalLines.MAIN:
				case TacticalLines.MAIN_STRAIGHT:
				case TacticalLines.AIRAOA:
				case TacticalLines.SPT:
				case TacticalLines.SPT_STRAIGHT:
					lResult = 2 * lElements + 8;
					break;
				case TacticalLines.FRONTAL_ATTACK:
					lResult = 2 * lElements + 15;
					break;
				case TacticalLines.TURNING_MOVEMENT:
					lResult = 2 * lElements + 14;
					break;
				case TacticalLines.MOVEMENT_TO_CONTACT:
					lResult = 2 * lElements + 24;
					break;
				case TacticalLines.CATK:
					lResult = 2 * lElements + 8;
					break;
				case TacticalLines.CATKBYFIRE:
					lResult = 2 * lElements + 17;
					break;
				case TacticalLines.AAAAA:
					lResult = 2 * lElements + 19;
					break;
				case TacticalLines.LC:
					pUpperLinePoints = Channels.GetChannelArray2Double(1, pUpperLinePoints, 1, lElements, tg.get_LineType(), ChannelWidth);
					pLowerLinePoints = Channels.GetChannelArray2Double(1, pLowerLinePoints, 0, lElements, tg.get_LineType(), ChannelWidth);
					lUpperFlotCount = flot.GetFlotCountDouble(pUpperLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), lElements);
					lLowerFlotCount = flot.GetFlotCountDouble(pLowerLinePoints, arraysupport.getScaledSize(20, tg.get_LineThickness(), tg.get_patternScale()), lElements);
					lResult = lUpperFlotCount + lLowerFlotCount;
					break;
				default:
					lResult = countsupport.GetCountersDouble(tg, lElements, pLinePoints, null);
					break;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(CELineArray._className, "CGetLineCountDouble", new RendererException("Failed inside CGetLineCount " + tg.get_LineType().toString(), exc));
			else throw exc;
		}
		return lResult;
	}
	/**
	* Return true is the line type is a channel type
	* @param lineType line type
	* @return
	*/
	static CIsChannel(lineType) {
		let lResult = 0;
		try {
			switch (lineType) {
				case TacticalLines.CATK:
				case TacticalLines.CATKBYFIRE:
				case TacticalLines.LC:
				case TacticalLines.AIRAOA:
				case TacticalLines.AAAAA:
				case TacticalLines.MAIN:
				case TacticalLines.MAIN_STRAIGHT:
				case TacticalLines.SPT:
				case TacticalLines.SPT_STRAIGHT:
				case TacticalLines.FRONTAL_ATTACK:
				case TacticalLines.TURNING_MOVEMENT:
				case TacticalLines.MOVEMENT_TO_CONTACT:
				case TacticalLines.UNSP:
				case TacticalLines.SFENCE:
				case TacticalLines.DFENCE:
				case TacticalLines.DOUBLEA:
				case TacticalLines.LWFENCE:
				case TacticalLines.HWFENCE:
				case TacticalLines.BBS_LINE:
				case TacticalLines.SINGLEC:
				case TacticalLines.DOUBLEC:
				case TacticalLines.TRIPLE:
				case TacticalLines.CHANNEL:
				case TacticalLines.CHANNEL_FLARED:
				case TacticalLines.CHANNEL_DASHED:
					lResult = 1;
					break;
				default:
					lResult = 0;
					break;
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(CELineArray._className, "CIsChannel", new RendererException("Failed inside CIsChannel " + lineType.toString(), exc));
			else throw exc;
		}
		return lResult;
	}
	static _client = "";
	static setClient(value) {
		CELineArray._client = value;
		Channels.setClient(value);
	}
	static getClient() {
		return CELineArray._client;
	}
};

