			let DPIScaleFactor = RendererSettings.getInstance().getDeviceDPI() / 96;
			if (d > 350 * DPIScaleFactor) d = 350 * DPIScaleFactor;
			else if (d < 100 * DPIScaleFactor) d = 100 * DPIScaleFactor;
