	static GetConvergencePointsDouble(pLinePoints, length, vblCounter) {
		let counter = vblCounter;
		try {
			let j = 0;
			let k = 0;
			let d = 0;
			let pt0 = new POINT2();
			let pt1 = new POINT2();
			let tempPts = new Array(vblCounter);
			let tempPt = new POINT2();
			let numJags = 0;
			for (j = 0; j < vblCounter; j++) tempPts[j] = new POINT2(pLinePoints[j]);
			pLinePoints[vblCounter - 1].style = 5;
			for (j = 0; j < vblCounter - 1; j++) {
				pt0 = new POINT2(tempPts[j]);
				pt1 = new POINT2(tempPts[j + 1]);
				d = lineutility.CalcDistanceDouble(pt0, pt1);
				numJags = Math.trunc(d / length);
				if (d - numJags * length < 5) numJags -= 1;
				for (k = 0; k < numJags; k++) {
					tempPt = lineutility.ExtendAlongLineDouble(pt0, pt1, k * length + length / 2, 0);
					pLinePoints[counter++] = new POINT2(tempPt);
					tempPt = lineutility.ExtendAlongLineDouble(tempPt, pt1, length / 2);
					tempPt = lineutility.ExtendDirectedLine(pt0, tempPt, tempPt, 2, length / 2, 5);
					pLinePoints[counter++] = new POINT2(tempPt);
					tempPt = lineutility.ExtendAlongLineDouble(pt0, pt1, (k + 1) * length, 0);
					pLinePoints[counter++] = new POINT2(tempPt);
					tempPt = lineutility.ExtendAlongLineDouble(tempPt, pt1, length / 2);
					tempPt = lineutility.ExtendDirectedLine(pt0, tempPt, tempPt, 3, length / 2, 5);
					pLinePoints[counter++] = new POINT2(tempPt);
				}
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(arraysupport._className, "GetConvergencePointsDouble", new RendererException("GetConvergencePointsDouble", exc));
			else throw exc;
		}
		return counter;
	}
	static GetITDPointsDouble(pLinePoints, length, vblCounter) {
		let counter = 0;
		try {
			let j = 0;
			let k = 0;
			let d = 0;
			let pt0 = new POINT2();
			let pt1 = new POINT2();
			let tempPts = new Array(vblCounter);
			let tempPt = new POINT2();
			let numJags = 0;
			let lineStyle = 19;
			for (j = 0; j < vblCounter; j++) tempPts[j] = new POINT2(pLinePoints[j]);
			for (j = 0; j < vblCounter - 1; j++) {
				pt0 = new POINT2(tempPts[j]);
				pt1 = new POINT2(tempPts[j + 1]);
				d = lineutility.CalcDistanceDouble(pt0, pt1);
				numJags = Math.trunc(d / length);
				if (d - numJags * length / 3 * 2 < length / 3) numJags -= 1;
				if (numJags === 0) {
					pt0.style = 19;
					pLinePoints[counter++] = new POINT2(pt0);
					pt1.style = 5;
					pLinePoints[counter++] = new POINT2(pt1);
				}
				for (k = 0; k < numJags; k++) {
					tempPt = lineutility.ExtendAlongLineDouble(pt0, pt1, k * length + length / 3, lineStyle);
					pLinePoints[counter++] = new POINT2(tempPt);
					if (k < numJags - 1) tempPt = lineutility.ExtendAlongLineDouble(tempPt, pt1, length * 2 / 3, 5);
					else {
						tempPt = new POINT2(tempPts[j + 1]);
						tempPt.style = 5;
					}
					pLinePoints[counter++] = new POINT2(tempPt);
					if (lineStyle === 19) lineStyle = 25;
					else lineStyle = 19;
				}
			}
		} catch (exc) {
			if (exc instanceof Error) ErrorLogger.LogException(arraysupport._className, "GetITDPointsDouble", new RendererException("GetITDPointsDouble", exc));
			else throw exc;
		}
		return counter;
	}
