					shape = new Shape2(Shape2.SHAPE_TYPE_POLYLINE);
					shape.moveTo(pLinePoints[3]);
					for (k = 4; k < 8; k++) shape.lineTo(pLinePoints[k]);
					shapes.push(shape);
					secondPoly = new Array(6);
					for (let i = 0; i < 6; i++) secondPoly[i] = pLinePoints[i + 8];
