					shape = new Shape2(Shape2.SHAPE_TYPE_POLYLINE);
					shape.moveTo(pLinePoints[acCounter - 10]);
					for (j = 9; j > 0; j--) if (pLinePoints[acCounter - j - 1].style === 5) shape.moveTo(pLinePoints[acCounter - j]);
					else shape.lineTo(pLinePoints[acCounter - j]);
