	static GeoJSONize(shapes, modifiers, ipc, normalize, textColor, textBackgroundColor) {
		let tempModifier;
		let fc = "";
		fc += "[";
		let len = shapes.length;
		for (let i = 0; i < len; i++) {
			let shapesToAdd = null;
			let tempShape = shapes[i];
			if (tempShape != null && tempShape !== void 0) {
				shapesToAdd = MultiPointHandler.ShapeToGeoJSONString(tempShape, ipc, normalize);
				if (shapesToAdd != null && shapesToAdd.length > 0) {
					fc += shapesToAdd;
					if (i < len - 1) fc += ",";
				}
			}
		}
		let len2 = modifiers.length;
		for (let j = 0; j < len2; j++) {
			tempModifier = modifiers[j];
			let modifiersToAdd;
			if (modifiers[j].getModifierImage() != null) modifiersToAdd = MultiPointHandler.ImageToGeoJSONString(tempModifier, ipc, normalize);
			else modifiersToAdd = MultiPointHandler.LabelToGeoJSONString(tempModifier, ipc, normalize, textColor, textBackgroundColor);
			if (modifiersToAdd.length > 0) {
				if (fc.length > 1) fc += ",";
				fc += modifiersToAdd;
			}
		}
		fc += "]";
		return fc.toString();
	}
